    /** A move button was clicked; index is into the active mon's moveset. */
    public synchronized void chooseMove(int moveIdx)
    {
        if (session == null || session.finished || session.myPendingMove != null)
        {
            return;
        }
        switch (session.mode)
        {
            case AI:
            {
                session.myPendingMove = moveIdx;
                session.resolveTurn(moveIdx, session.aiMove());
                // Cosmetics must never gate settlement: a throw out of the
                // scene once skipped finishBattle entirely, silently eating
                // gym claims, badges, and xp on won fights
                try
                {
                    battleScene.clash(session.myMon().lastHitTaken, session.oppMon().lastHitTaken);
                }
                catch (Exception e)
                {
                    log.warn("battle scene clash failed", e);
                }
                if (session.finished)
                {
                    finishBattle();
                }
                break;
            }
            case PVP_HOST:
            {
                session.myPendingMove = moveIdx;
                tryResolveHostTurn();
                break;
            }
            case PVP_GUEST:
            {
                session.myPendingMove = moveIdx;
                partyService.send(new BattleMoveMsg(session.battleId, session.turn, moveIdx));
                break;
            }
        }
        refreshPanel();
    }

    private void tryResolveHostTurn()
    {
        if (session == null || session.myPendingMove == null || session.oppPendingMove == null)
        {
            return;
        }
        int sentTurn = session.turn;
        List<String> log = session.resolveTurn(session.myPendingMove, session.oppPendingMove);
        try
        {
            battleScene.clash(session.myMon().lastHitTaken, session.oppMon().lastHitTaken);
        }
        catch (Exception e)
        {
            OsrsGoPlugin.log.warn("battle scene clash failed", e);
        }
        TurnState state = session.snapshot(log);
        partyService.send(new BattleTurnResultMsg(session.battleId, sentTurn, gson.toJson(state)));
        if (session.finished)
        {
            finishBattle();
        }
    }

    public synchronized void forfeit()
    {
        if (session == null)
        {
            return;
        }
        if (session.mode != BattleSession.Mode.AI && partyService.isInParty())
        {
            partyService.send(new BattleEndMsg(session.battleId, "forfeit"));
        }
        session.finished = true;
        session.wonByMe = false;
        session.fullLog.add("You forfeited the battle.");
        syncTeamHp();
        if (session.raidSpeciesId != null)
        {
            // Raid retreats carry no penalty beyond the damage taken
        }
        else if (session.gymId != null)
        {
            profile.stats.gymLosses++;
        }
        else
        {
            profile.stats.pvpLosses++;
        }
        saveSoon();
        refreshPanel();
    }

    public synchronized void closeBattle()
    {
        session = null;
        battleTeamRefs = Collections.emptyList();
        refreshPanel();
    }


    /** How a battle settled and what it triggered. Log only, never shown in game. */
    private void battleDiag(String line)
    {
        log.debug("battle end | {}", line);
    }

    private void finishBattle()
    {
        if (session == null)
        {
            return;
        }
        syncTeamHp();
        if (session.wonByMe)
        {
            battleScene.celebrate();
        }
        if (session.raidSpeciesId != null)
        {
            battleDiag(session.battleId + " " + (session.wonByMe ? "WON" : "LOST")
                + " [raid] -> throws roll; raids never claim gyms");
            // Win or lose, a finished raid fight burns this rotation's attempt
            if (session.battleId != null && session.battleId.startsWith("raid-"))
            {
                recordRaidAttempt(session.battleId.substring("raid-".length()));
            }
            if (session.wonByMe)
            {
                finishRaid();
            }
            saveSoon();
            refreshPanel();
            return;
        }
        battleDiag(session.battleId + " " + (session.wonByMe ? "WON" : "LOST")
            + (session.gymId != null
                ? (session.gymHolderRsn != null ? " [gym vs " + session.gymHolderRsn + "]" : " [gym, unclaimed]")
                : " [pvp]")
            + (session.wonByMe && session.gymId != null ? " -> claiming" : ""));
        if (session.gymId != null)
        {
            if (session.wonByMe)
            {
                profile.stats.gymWins++;
                researchEvent(com.osrsgo.data.ResearchData.Kind.WIN_GYM, 1);
            }
            else
            {
                profile.stats.gymLosses++;
            }
        }
        else if (session.wonByMe)
        {
            profile.stats.pvpWins++;
        }
        else
        {
            profile.stats.pvpLosses++;
        }
        if (session.wonByMe)
        {
            int oppLevels = 0;
            for (BattleMon m : session.oppTeam)
            {
                oppLevels += m.level;
            }
            int avgOpp = session.oppTeam.isEmpty() ? 1 : oppLevels / session.oppTeam.size();
            grantBattleMonXp(avgOpp);
            if (session.gymId != null)
            {
                GymData.Gym gym = GymData.byId(session.gymId);
                if (gym != null && !profile.badges.contains(gym.badge))
                {
                    profile.badges.add(gym.badge);
                    session.fullLog.add("You earned the " + gym.badge + "!");
                    chatMessage("Gielinor Safari: you earned the " + gym.badge + "!");
                }
                profile.trainerXp += 150;
                if (gym != null && config.gymControl())
                {
                    chatMessage("Gielinor Safari: gym win at " + gym.name + ", claiming it...");
                }
                claimGymAfterWin(gym);
            }
            else
            {
                profile.trainerXp += 100;
                chatMessage("Gielinor Safari: you won the battle against " + session.opponentName + "!");
            }
        }
        else if (session.gymHolderRsn != null && config.gymControl() && myRsn != null)
        {
            if (session.holderTeamDefeated())
            {
                breakGymAfterPartialWin();
            }
            else
            {
                com.osrsgo.gym.LocalGyms.recordDefense(profile.gyms, session.gymId);
                saveSoon();
            }
        }
        saveSoon();
    }

    /**
     * The challenger beat the holder's defender team but lost to the NPC
     * leader: the hold is broken and the gym reverts to unclaimed.
     */
    private void breakGymAfterPartialWin()
    {
        GymData.Gym gym = GymData.byId(session.gymId);
        if (gym == null)
        {
            return;
        }
        String holderRsn = session.gymHolderRsn;
        com.osrsgo.gym.LocalGyms.breakHold(profile.gyms, gym.id);
        saveSoon();
        chatMessage("Gielinor Safari: you crushed " + holderRsn + "'s defenders, but "
            + gym.leader + " stopped you. " + gym.name + " now stands unclaimed!");
        // Without this the holder's client keeps the gym and the two of you
        // disagree about it permanently
        broadcastGymBreak(gym.id);
        refreshPanel();
    }

    private void broadcastGymBreak(String gymId)
    {
        if (!partyService.isInParty())
        {
            return;
        }
        partyService.send(new com.osrsgo.party.GymBreakMsg(gymId));
    }

    private void broadcastGymClaim(String gymId)
    {
        GymHolder holder = profile.gyms.get(gymId);
        if (holder == null || !partyService.isInParty())
        {
            return;
        }
        partyService.send(new com.osrsgo.party.GymClaimMsg(gymId, holder.holderRsn,
            gson.toJson(holder.holderTeam), holder.holderFaction));
    }

    private void claimGymAfterWin(GymData.Gym gym)
    {
        if (gym == null || !config.gymControl() || myRsn == null || battleTeamRefs.isEmpty())
        {
            String why = gym == null ? "the gym was unknown"
                : !config.gymControl() ? "Gym control is OFF in settings"
                : myRsn == null ? "your RSN wasn't loaded yet" : "the battle team reference was empty";
            battleDiag("claim skipped: " + why);
            // Silent skips here cost hours of "I beat it and nothing happened"
            chatAlways("Gielinor Safari: your win did NOT claim "
                + (gym != null ? gym.name : "the gym") + " because " + why + ".");
            return;
        }
        com.osrsgo.gym.LocalGyms.claim(profile.gyms, gym.id, myRsn,
            specsOf(battleTeamRefs), client.getWorld(), profile.faction);
        profile.stats.gymsCaptured++;
        battleDiag("claim " + gym.id + " OK");
        saveSoon();
        chatMessage("Gielinor Safari: you now hold " + gym.name + "! Your team stands guard.");
        broadcastGymClaim(gym.id);
        refreshPanel();
    }

    @Subscribe
    public synchronized void onGymClaimMsg(com.osrsgo.party.GymClaimMsg msg)
    {
        if (isEcho(msg.getMemberId()) || !config.gymControl()
            || GymData.byId(msg.getGymId()) == null || msg.getHolderRsn() == null)
        {
            return;
        }
        // Bind the holder name to whoever actually sent this, or any party
        // member can claim (or hand away) any gym under any name, and
        // gymsHeldNow() feeds tribute, the catch bonus and the monarch bonus.
        // Both sides go through toJagexName first: an RSN carries a
        // non-breaking space where a space is displayed, so a raw comparison
        // silently rejects every player whose name has a space in it.
        net.runelite.client.party.PartyMember sender = partyService.getMemberById(msg.getMemberId());
        if (sender == null || !jagexName(msg.getHolderRsn()).equalsIgnoreCase(jagexName(sender.getDisplayName())))
        {
            return;
        }
        String faction = msg.getFaction();
        if (faction != null && !faction.equals("SARADOMIN") && !faction.equals("ZAMORAK")
            && !faction.equals("GUTHIX"))
        {
            // A malformed faction means a malformed sender: treat the whole
            // message as hostile rather than silently nulling the field
            return;
        }
        List<MonSpec> team = new ArrayList<>();
        try
        {
            MonSpec[] raw = gson.fromJson(msg.getTeamJson(), MonSpec[].class);
            if (raw != null)
            {
                for (MonSpec spec : raw)
                {
                    if (com.osrsgo.battle.SpecValidator.valid(spec))
                    {
                        team.add(spec);
                    }
                }
            }
        }
        catch (Exception e)
        {
            log.warn("bad party gym claim", e);
            return;
        }
        if (team.isEmpty() || team.size() > MAX_CLAIM_TEAM)
        {
            log.warn("party gym claim for {} carried {} valid mons; ignoring",
                msg.getGymId(), team.size());
            return;
        }
        com.osrsgo.gym.LocalGyms.claim(profile.gyms, msg.getGymId(), msg.getHolderRsn(),
            team, null, faction);
        saveSoon();
        GymData.Gym gym = GymData.byId(msg.getGymId());
        chatMessage("Gielinor Safari: " + msg.getHolderRsn() + " took " + gym.name + "!");
        refreshPanel();
    }

    @Subscribe
    public synchronized void onGymBreakMsg(com.osrsgo.party.GymBreakMsg msg)
    {
        if (isEcho(msg.getMemberId()) || !config.gymControl() || GymData.byId(msg.getGymId()) == null)
        {
            return;
        }
        // A break costs the sender a real gym battle, so one per minute per
        // sender is generous. Without this any peer can loop breaks over all
        // ten gyms and hold the whole party at zero tribute forever.
        long now = System.currentTimeMillis();
        Long lastBreak = lastBreakFromMember.get(msg.getMemberId());
        if (lastBreak != null && now - lastBreak < BREAK_COOLDOWN_MS)
        {
            return;
        }
        lastBreakFromMember.put(msg.getMemberId(), now);
        GymHolder losing = profile.gyms.get(msg.getGymId());
        boolean wasMine = losing != null && myRsn != null && losing.isHeldBy(myRsn);
        com.osrsgo.gym.LocalGyms.breakHold(profile.gyms, msg.getGymId());
        if (wasMine)
        {
            // Losing tribute silently is how a griefer stays invisible
            GymData.Gym gym = GymData.byId(msg.getGymId());
            chatMessage("Gielinor Safari: your hold on " + gym.name + " was broken. It stands unclaimed.");
        }
        saveSoon();
        refreshPanel();
    }

    /**
     * RSNs and party display names spell the same player differently: the RSN
     * keeps the non-breaking space the game stores, the display name has been
     * normalised. Compare them only through here.
     */
    private static String jagexName(String name)
    {
        return name == null ? "" : net.runelite.client.util.Text.toJagexName(name);
    }

    /** True when this holder name belongs to someone currently in the party. */
    public boolean isPartyMemberName(String rsn)
    {
        if (rsn == null || !partyService.isInParty())
        {
            return false;
        }
        for (net.runelite.client.party.PartyMember member : partyService.getMembers())
        {
            if (jagexName(rsn).equalsIgnoreCase(jagexName(member.getDisplayName())))
            {
                return true;
            }
        }
        return false;
    }

    // ------------------------------------------------------------------ party message handlers



    @Subscribe
    public synchronized void onBattleChallengeMsg(BattleChallengeMsg msg)
    {
        if (isEcho(msg.getMemberId()) || localMemberId() != msg.getTargetId())
        {
            return;
        }
        pendingBattleId = msg.getBattleId();
        pendingChallengerId = msg.getMemberId();
        pendingChallengerName = msg.getChallengerName();
        pendingChallengerTeamJson = msg.getTeamJson();
        notifier.notify("Gielinor Safari: " + msg.getChallengerName() + " challenged you to a battle!");
        refreshPanel();
    }

    @Subscribe
    public synchronized void onBattleAcceptMsg(BattleAcceptMsg msg)
    {
        if (isEcho(msg.getMemberId()) || outgoingBattleId == null || !outgoingBattleId.equals(msg.getBattleId()))
        {
            return;
        }
        List<OwnedMon> team = battleReadyTeam();
        if (team.isEmpty() || session != null)
        {
            return;
        }
        List<BattleMon> mine = new ArrayList<>();
        for (OwnedMon m : team)
        {
            mine.add(BattleMon.fromOwned(m));
        }
        List<BattleMon> theirs = specsToMons(msg.getTeamJson());
        battleTeamRefs = team;
        session = new BattleSession(BattleSession.Mode.PVP_HOST, outgoingBattleId,
            msg.getAccepterName(), msg.getMemberId(), null, mine, theirs);
        session.fullLog.add("Battle vs " + msg.getAccepterName() + " begins!");
        outgoingBattleId = null;
        refreshPanel();
    }

    @Subscribe
    public synchronized void onBattleDeclineMsg(BattleDeclineMsg msg)
    {
        if (isEcho(msg.getMemberId()))
        {
            return;
        }
        if (outgoingBattleId != null && outgoingBattleId.equals(msg.getBattleId()))
        {
            outgoingBattleId = null;
            panelToast("Your challenge was declined.");
            refreshPanel();
        }
    }

    @Subscribe
    public synchronized void onBattleMoveMsg(BattleMoveMsg msg)
    {
        if (isEcho(msg.getMemberId()) || session == null || session.mode != BattleSession.Mode.PVP_HOST
            || !session.battleId.equals(msg.getBattleId()) || msg.getTurn() != session.turn)
        {
            return;
        }
        session.oppPendingMove = msg.getMoveIndex();
        tryResolveHostTurn();
        refreshPanel();
    }

    @Subscribe
    public synchronized void onBattleTurnResultMsg(BattleTurnResultMsg msg)
    {
        if (isEcho(msg.getMemberId()) || session == null || session.mode != BattleSession.Mode.PVP_GUEST
            || !session.battleId.equals(msg.getBattleId()))
        {
            return;
        }
        try
        {
            TurnState state = gson.fromJson(msg.getStateJson(), TurnState.class);
            session.applySnapshot(state);
            battleScene.clash(session.myMon().lastHitTaken, session.oppMon().lastHitTaken);
            if (session.finished)
            {
                finishBattle();
            }
        }
        catch (Exception e)
        {
            log.warn("Bad turn state from host", e);
        }
        refreshPanel();
    }

    @Subscribe
    public synchronized void onBattleEndMsg(BattleEndMsg msg)
    {
        if (isEcho(msg.getMemberId()) || session == null || !session.battleId.equals(msg.getBattleId()))
        {
            return;
        }
        if (!session.finished)
        {
            session.finished = true;
            session.wonByMe = true;
            session.fullLog.add(session.opponentName + " forfeited. You win!");
            finishBattle();
        }
        refreshPanel();
    }

    @Subscribe
    public synchronized void onPartyChanged(PartyChanged event)
    {
        // Leaving the party invalidates any pvp state
        if (!partyService.isInParty())
        {
            if (session != null && session.mode != BattleSession.Mode.AI && !session.finished)
            {
                session.finished = true;
                session.wonByMe = false;
                session.fullLog.add("Party disbanded; battle abandoned.");
                syncTeamHp();
                saveSoon();
            }
            outgoingBattleId = null;
            clearPendingChallenge();
            trade = null;
            clearIncomingTrade();
            refreshPanel();
        }
    }

    // ------------------------------------------------------------------ helpers

    private List<MonSpec> specsOf(List<OwnedMon> team)
    {
        List<MonSpec> specs = new ArrayList<>();
        for (OwnedMon m : team)
        {
            specs.add(MonSpec.fromOwned(m));
        }
        return specs;
    }

    private List<BattleMon> specsToMons(String teamJson)
    {
        List<BattleMon> mons = new ArrayList<>();
        try
        {
            MonSpec[] specs = gson.fromJson(teamJson, MonSpec[].class);
            if (specs != null)
            {
                for (MonSpec s : specs)
                {
                    if (com.osrsgo.battle.SpecValidator.valid(s))
                    {
                        mons.add(BattleMon.fromSpec(s));
                    }
                    else
                    {
                        log.warn("Rejected impossible mon spec from opponent: species {} lvl {}",
                            s != null ? s.speciesId : -1, s != null ? s.level : -1);
                    }
                }
            }
        }
        catch (Exception e)
        {
            log.warn("Bad team json", e);
        }
        if (mons.isEmpty())
        {
            mons.add(BattleMon.fromSpecies(3, 5));
        }
        return mons;
    }

    private boolean isEcho(long memberId)
    {
        return localMemberId() == memberId;
    }

    private long localMemberId()
    {
        PartyMember local = partyService.getLocalMember();
        return local != null ? local.getMemberId() : -1;
    }

    private String localName()
    {
        PartyMember local = partyService.getLocalMember();
        return local != null && local.getDisplayName() != null ? local.getDisplayName() : "Trainer";
    }

    private void clearPendingChallenge()
    {
        pendingBattleId = null;
        pendingChallengerId = -1;
        pendingChallengerName = null;
        pendingChallengerTeamJson = null;
    }

    /** Milestone messages; muted by the 'Chat: milestones' toggle. */
    private void chatMessage(String message)
    {
        if (config.chatMilestones())
        {
            chatAlways(message);
        }
    }

    /** Travel-find messages; muted by the 'Chat: travel finds' toggle. */
    private void chatFind(String message)
    {
        if (config.chatFinds())
        {
            chatAlways(message);
        }
    }

    /** Warnings that must never be muted (lost claims, tampered profiles). */
    private void chatAlways(String message)
    {
        clientThread.invokeLater(() ->
        {
            if (client.getGameState() == GameState.LOGGED_IN)
            {
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
            }
        });
    }

    private void panelToast(String message)
    {
        if (panel != null)
        {
            panel.showToast(message);
        }
    }

    private void refreshPanel()
    {
        if (panel != null)
        {
            panel.refreshLater();
        }
    }

    // ------------------------------------------------------------------ debounced persistence
    // Saving = full profile JSON + HMAC + a config write that broadcasts to
    // every plugin. Walking research once triggered that EVERY TICK; now dirty
    // state flushes at most every 10 ticks (~6s), plus on shutdown.

    private volatile boolean profileDirty;

    private void saveSoon()
    {
        profileDirty = true;
    }

    private void flushProfileIfDirty()
    {
        if (profileDirty)
        {
            profileDirty = false;
            // Serialization grows with the collection; keep it OFF the client
            // thread. The lock keeps mutators (all synchronized) consistent.
            executor.execute(() ->
            {
                synchronized (OsrsGoPlugin.this)
                {
                    profileStore.save(profile);
                }
            });
        }
    }

}

package com.osrsgo.anim;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Animations learned from watching real NPCs play. Idle and walk come
 * straight off any live NPC of the species; attack animations are voted in
 * from observed combat (3+ sightings of the same sequence) so a one-off
 * death or flinch can't win. Persisted locally so knowledge accumulates.
 */
@Slf4j
@Singleton
public class AnimationLibrary
{
    public static class Entry
    {
        public int idle = -1;
        public int walk = -1;
        public int attack = -1;
    }

    /** Persisted shape: species-keyed entries plus a universal name-keyed store. */
    public static class Store
    {
        public Map<Integer, Entry> species = new HashMap<>();
        public Map<String, Entry> names = new HashMap<>();
    }

    private final File file = com.osrsgo.storage.PluginFiles.file("anims.json");
    private final Gson gson;
    private final Map<Integer, Entry> bySpecies = new HashMap<>();
    private final Map<String, Entry> byName = new HashMap<>();
    private final Map<Integer, Map<Integer, Integer>> attackVotes = new HashMap<>();
    private final Map<String, Map<Integer, Integer>> attackVotesByName = new HashMap<>();
    private boolean dirty;

    @Inject
    public AnimationLibrary(Gson gson)
    {
        this.gson = gson;
        load();
    }

    private Entry nameEntryForSpecies(int speciesId)
    {
        com.osrsgo.model.Species sp = com.osrsgo.data.SpeciesData.byId(speciesId);
        return sp != null ? byName.get(sp.getName().toLowerCase()) : null;
    }

    public synchronized Integer idleFor(int speciesId)
    {
        Entry e = bySpecies.get(speciesId);
        if (e != null && e.idle > -1)
        {
            return e.idle;
        }
        Entry n = nameEntryForSpecies(speciesId);
        return n != null && n.idle > -1 ? n.idle : null;
    }

    public synchronized Integer walkFor(int speciesId)
    {
        Entry e = bySpecies.get(speciesId);
        if (e != null && e.walk > -1)
        {
            return e.walk;
        }
        Entry n = nameEntryForSpecies(speciesId);
        return n != null && n.walk > -1 ? n.walk : null;
    }

    public synchronized Integer attackFor(int speciesId)
    {
        Entry e = bySpecies.get(speciesId);
        if (e != null && e.attack > -1)
        {
            return e.attack;
        }
        Entry n = nameEntryForSpecies(speciesId);
        return n != null && n.attack > -1 ? n.attack : null;
    }

    /** Universal learning: every named NPC teaches its poses, catalog or not. */
    public synchronized void learnPoseByName(String name, int idlePose, int walkAnim)
    {
        Entry e = byName.computeIfAbsent(name, k -> new Entry());
        if (idlePose > -1 && e.idle != idlePose)
        {
            e.idle = idlePose;
            dirty = true;
        }
        if (walkAnim > -1 && e.walk != walkAnim)
        {
            e.walk = walkAnim;
            dirty = true;
        }
    }

    public synchronized void voteAttackByName(String name, int animId)
    {
        if (animId <= -1)
        {
            return;
        }
        Map<Integer, Integer> votes = attackVotesByName.computeIfAbsent(name, k -> new HashMap<>());
        votes.merge(animId, 1, Integer::sum);
        int bestAnim = -1;
        int bestCount = 0;
        for (Map.Entry<Integer, Integer> v : votes.entrySet())
        {
            if (v.getValue() > bestCount)
            {
                bestCount = v.getValue();
                bestAnim = v.getKey();
            }
        }
        if (bestCount >= 3)
        {
            Entry e = byName.computeIfAbsent(name, k -> new Entry());
            if (e.attack != bestAnim)
            {
                e.attack = bestAnim;
                dirty = true;
            }
        }
    }

    /** Poses read straight off a live NPC of this species. */
    public synchronized void learnPose(int speciesId, int idlePose, int walkAnim)
    {
        Entry e = bySpecies.computeIfAbsent(speciesId, k -> new Entry());
        if (idlePose > -1 && e.idle != idlePose)
        {
            e.idle = idlePose;
            dirty = true;
        }
        if (walkAnim > -1 && e.walk != walkAnim)
        {
            e.walk = walkAnim;
            dirty = true;
        }
    }

    /** A combat sequence animation seen on this species; majority wins at 3+ votes. */
    public synchronized void voteAttack(int speciesId, int animId)
    {
        if (animId <= -1)
        {
            return;
        }
        Map<Integer, Integer> votes = attackVotes.computeIfAbsent(speciesId, k -> new HashMap<>());
        votes.merge(animId, 1, Integer::sum);
        int bestAnim = -1;
        int bestCount = 0;
        for (Map.Entry<Integer, Integer> v : votes.entrySet())
        {
            if (v.getValue() > bestCount)
            {
                bestCount = v.getValue();
                bestAnim = v.getKey();
            }
        }
        if (bestCount >= 3)
        {
            Entry e = bySpecies.computeIfAbsent(speciesId, k -> new Entry());
            if (e.attack != bestAnim)
            {
                e.attack = bestAnim;
                dirty = true;
            }
        }
    }

    public synchronized void saveIfDirty()
    {
        if (!dirty)
        {
            return;
        }
        try
        {
            Store store = new Store();
            store.species = bySpecies;
            store.names = byName;
            Files.write(file.toPath(), gson.toJson(store).getBytes(StandardCharsets.UTF_8));
            dirty = false;
        }
        catch (Exception e)
        {
            log.warn("could not save animation library", e);
        }
    }

    private void load()
    {
        if (!file.isFile())
        {
            return;
        }
        try
        {
            String json = new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8);
            if (json.contains("\"names\""))
            {
                Store store = gson.fromJson(json, Store.class);
                if (store != null)
                {
                    if (store.species != null)
                    {
                        bySpecies.putAll(store.species);
                    }
                    if (store.names != null)
                    {
                        byName.putAll(store.names);
                    }
                }
            }
            else
            {
                // Pre-universal format: a bare species map
                Map<Integer, Entry> loaded = gson.fromJson(json,
                    new TypeToken<Map<Integer, Entry>>()
                    {
                    }.getType());
                if (loaded != null)
                {
                    bySpecies.putAll(loaded);
                }
            }
        }
        catch (Exception e)
        {
            log.warn("could not load animation library", e);
        }
    }

    /** How much the library knows, for the curious. */
    public synchronized String summary()
    {
        return bySpecies.size() + " species + " + byName.size() + " npc names learned";
    }
}

package com.osrsgo.battle;

import com.osrsgo.data.MoveData;
import com.osrsgo.model.Move;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Resolves one battle turn. Pure logic: no client, no Swing, no party. The
 * same engine runs gym (AI) battles locally and PvP battles on the host.
 */
public final class BattleEngine
{
    /** Resolves a full turn between two active mons. Appends to and returns the log. */
    public static List<String> resolveTurn(BattleMon first, Move firstMove, BattleMon second, Move secondMove, Random rng)
    {
        List<String> log = new ArrayList<>();
        first.lastHitTaken = -1;
        second.lastHitTaken = -1;
        first.guarding = firstMove.isGuard();
        second.guarding = secondMove.isGuard();

        act(first, firstMove, second, rng, log);
        if (!second.fainted())
        {
            act(second, secondMove, first, rng, log);
        }
        first.guarding = false;
        second.guarding = false;
        return log;
    }

    private static void act(BattleMon attacker, Move move, BattleMon defender, Random rng, List<String> log)
    {
        if (attacker.fainted())
        {
            return;
        }
        if (move.isGuard())
        {
            // Guarding breaks the repetition streak, like any move change
            attacker.lastMoveId = move.getId();
            attacker.repeatCount = 0;
            log.add(attacker.name + " braces behind its guard.");
            return;
        }
        if (move.getId() == attacker.lastMoveId)
        {
            attacker.repeatCount++;
        }
        else
        {
            attacker.repeatCount = 0;
        }
        attacker.lastMoveId = move.getId();
        if (rng.nextDouble() > move.getAccuracy())
        {
            log.add(attacker.name + "'s " + move.getName() + " missed!");
            defender.lastHitTaken = 0;
            return;
        }
        int damage = damage(attacker, move, defender, rng);
        defender.hp = Math.max(0, defender.hp - damage);
        defender.lastHitTaken = damage;
        double mult = move.getType().multiplierAgainst(defender.type);
        String effect = mult > 1.0 ? " A devastating blow!" : (mult < 1.0 ? " It barely leaves a mark." : "");
        String fatigue = attacker.repeatCount > 0
            ? " Fatigue sets in (-" + Math.round((1 - fatigueFactor(attacker.repeatCount)) * 100) + "%)."
            : "";
        log.add(attacker.name + " used " + move.getName() + "! " + damage + " damage." + effect + fatigue);
        if (defender.fainted())
        {
            log.add(defender.name + " fainted!");
        }
    }

    /** Damage multiplier for the Nth consecutive use of the same move: 100/70/50/40% floor. */
    static double fatigueFactor(int repeatCount)
    {
        return Math.max(0.4, 1.0 - 0.3 * repeatCount);
    }

    static int damage(BattleMon attacker, Move move, BattleMon defender, Random rng)
    {
        double base = ((2.0 * attacker.level / 5.0 + 2.0) * move.getPower() * attacker.atk / Math.max(1, defender.def)) / 50.0 + 2.0;
        double mult = move.getType().multiplierAgainst(defender.type);
        double roll = 0.85 + rng.nextDouble() * 0.15;
        double dmg = base * mult * roll * fatigueFactor(attacker.repeatCount);
        if (defender.guarding)
        {
            dmg /= 2.0;
        }
        return Math.max(1, (int) Math.round(dmg));
    }

    /** Highest expected damage move (fatigue-aware), with a 20% chance to pick randomly instead. */
    public static int pickAiMove(BattleMon self, BattleMon target, Random rng)
    {
        List<Integer> ids = self.moveIds;
        if (rng.nextDouble() < 0.20)
        {
            return rng.nextInt(ids.size());
        }
        int bestIdx = 0;
        double bestScore = -1;
        for (int i = 0; i < ids.size(); i++)
        {
            Move m = MoveData.byId(ids.get(i));
            double score;
            if (m.isGuard())
            {
                score = 5;
            }
            else
            {
                score = m.getPower() * m.getAccuracy() * m.getType().multiplierAgainst(target.type);
                if (m.getId() == self.lastMoveId)
                {
                    score *= fatigueFactor(self.repeatCount + 1);
                }
            }
            if (score > bestScore)
            {
                bestScore = score;
                bestIdx = i;
            }
        }
        return bestIdx;
    }

    private BattleEngine()
    {
    }
}

package com.osrsgo.battle;

import com.osrsgo.data.MoveData;
import com.osrsgo.data.SpeciesData;
import com.osrsgo.model.MonType;
import com.osrsgo.model.OwnedMon;
import com.osrsgo.model.Species;
import java.util.List;

/** Runtime battle state for one mon. */
public class BattleMon
{
    public final int speciesId;
    public final String name;
    public final MonType type;
    public final int level;
    public final int maxHp;
    public final int atk;
    public final int def;
    public final int spd;
    public final List<Integer> moveIds;
    public int hp;
    public boolean guarding;
    // Damage taken in the most recent turn (-1 none, 0 = miss/blocked), for hitsplats
    public int lastHitTaken = -1;
    // Repetition fatigue: consecutive uses of the same damaging move weaken it
    public int lastMoveId = -1;
    public int repeatCount;

    private BattleMon(int speciesId, int level, int maxHp, int atk, int def, int spd)
    {
        this(speciesId, level, maxHp, atk, def, spd, null);
    }

    private BattleMon(int speciesId, int level, int maxHp, int atk, int def, int spd, String nameOverride)
    {
        Species s = SpeciesData.byId(speciesId);
        this.speciesId = speciesId;
        this.name = nameOverride != null ? nameOverride : s.getName();
        this.type = s.getType();
        this.level = level;
        this.maxHp = maxHp;
        this.atk = atk;
        this.def = def;
        this.spd = spd;
        this.moveIds = MoveData.movesetFor(s.getType(), s.getRarity());
        this.hp = maxHp;
    }

    public static BattleMon fromOwned(OwnedMon m)
    {
        BattleMon b = new BattleMon(m.speciesId, m.level, m.maxHp(), m.atk(), m.def(), m.spd(), m.displayName());
        b.hp = m.currentHp();
        return b;
    }

    public static BattleMon fromSpec(MonSpec s)
    {
        return new BattleMon(s.speciesId, s.level, s.maxHp, s.atk, s.def, s.spd);
    }

    /** Builds an NPC combatant (gym teams, wild mons) with average IVs. */
    public static BattleMon fromSpecies(int speciesId, int level)
    {
        Species s = SpeciesData.byId(speciesId);
        int maxHp = ((s.getBaseHp() * 2 + 8) * level) / 100 + level + 10;
        int atk = ((s.getBaseAtk() * 2 + 8) * level) / 100 + 5;
        int def = ((s.getBaseDef() * 2 + 8) * level) / 100 + 5;
        int spd = ((s.getBaseSpd() * 2 + 8) * level) / 100 + 5;
        return new BattleMon(speciesId, level, maxHp, atk, def, spd);
    }

    public boolean fainted()
    {
        return hp <= 0;
    }
}

package com.osrsgo.battle;

import com.osrsgo.data.MoveData;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * State for one active battle, from either participant's perspective.
 * AI and PVP_HOST run the engine; PVP_GUEST only mirrors TurnState snapshots
 * broadcast by the host.
 */
public class BattleSession
{
    public enum Mode
    {
        AI,
        PVP_HOST,
        PVP_GUEST
    }

    public final Mode mode;
    public final String battleId;
    public final String opponentName;
    public final long opponentMemberId;
    public final String gymId;
    public final List<BattleMon> myTeam;
    public final List<BattleMon> oppTeam;
    public int myActive;
    public int oppActive;
    public int turn = 1;
    public boolean finished;
    public boolean wonByMe;
    public final List<String> fullLog = new ArrayList<>();

    public Integer myPendingMove;
    public Integer oppPendingMove;

    // Gym-control context: set when this AI battle is against another
    // trainer's defender team rather than the NPC leader.
    public String gymHolderRsn;
    public String gymExpectedUpdatedAt;
    // When battling a claimed gym, the enemy list is the holder's defender
    // team (indices 0..gymHolderMonCount-1) followed by the NPC leader's team.
    public int gymHolderMonCount;
    // Set when this AI battle is a raid boss fight
    public Integer raidSpeciesId;
    // Which of my team slots scored each enemy KO, for bonus xp
    public final List<Integer> koScorers = new ArrayList<>();

    private final Random rng = new Random();

    public BattleSession(Mode mode, String battleId, String opponentName, long opponentMemberId,
        String gymId, List<BattleMon> myTeam, List<BattleMon> oppTeam)
    {
        this.mode = mode;
        this.battleId = battleId;
        this.opponentName = opponentName;
        this.opponentMemberId = opponentMemberId;
        this.gymId = gymId;
        this.myTeam = myTeam;
        this.oppTeam = oppTeam;
    }

    public BattleMon myMon()
    {
        return myTeam.get(myActive);
    }

    public BattleMon oppMon()
    {
        return oppTeam.get(oppActive);
    }

    /** Whose mon is currently facing you: the gym holder during their phase, else the named opponent. */
    public String currentOpponentName()
    {
        return gymHolderRsn != null && oppActive < gymHolderMonCount ? gymHolderRsn : opponentName;
    }

    /** True once every mon of the holder's defender team has fainted. */
    public boolean holderTeamDefeated()
    {
        if (gymHolderMonCount <= 0)
        {
            return false;
        }
        for (int i = 0; i < gymHolderMonCount && i < oppTeam.size(); i++)
        {
            if (!oppTeam.get(i).fainted())
            {
                return false;
            }
        }
        return true;
    }

    /**
     * Resolves a turn locally (AI and PVP_HOST modes). Move indices are into
     * each active mon's moveset. Returns the log lines for this turn.
     */
    public List<String> resolveTurn(int myMoveIdx, int oppMoveIdx)
    {
        BattleMon mine = myMon();
        BattleMon theirs = oppMon();
        com.osrsgo.model.Move myMove = MoveData.byId(mine.moveIds.get(clamp(myMoveIdx, mine.moveIds.size())));
        com.osrsgo.model.Move oppMove = MoveData.byId(theirs.moveIds.get(clamp(oppMoveIdx, theirs.moveIds.size())));

        boolean iGoFirst = mine.spd > theirs.spd || (mine.spd == theirs.spd && rng.nextBoolean());
        List<String> log = iGoFirst
            ? BattleEngine.resolveTurn(mine, myMove, theirs, oppMove, rng)
            : BattleEngine.resolveTurn(theirs, oppMove, mine, myMove, rng);

        handleFaints(log);
        turn++;
        myPendingMove = null;
        oppPendingMove = null;
        fullLog.addAll(log);
        return log;
    }

    private void handleFaints(List<String> log)
    {
        if (myMon().fainted())
        {
            int next = nextAlive(myTeam);
            if (next < 0)
            {
                finished = true;
                wonByMe = false;
                log.add("You are out of mons. Defeat!");
            }
            else
            {
                myActive = next;
                log.add("You send out " + myMon().name + "!");
            }
        }
        if (!finished && oppMon().fainted())
        {
            koScorers.add(myActive);
            boolean wasHolderPhase = gymHolderRsn != null && oppActive < gymHolderMonCount;
            int next = nextAlive(oppTeam);
            if (next < 0)
            {
                finished = true;
                wonByMe = true;
                log.add("Victory! " + opponentName + " is out of mons.");
            }
            else
            {
                oppActive = next;
                if (wasHolderPhase && next >= gymHolderMonCount)
                {
                    log.add(gymHolderRsn + "'s defenders are down! " + opponentName
                        + " steps up to defend the gym itself!");
                }
                log.add(currentOpponentName() + " sends out " + oppMon().name + "!");
            }
        }
    }

    private static int nextAlive(List<BattleMon> team)
    {
        for (int i = 0; i < team.size(); i++)
        {
            if (!team.get(i).fainted())
            {
                return i;
            }
        }
        return -1;
    }

    public int aiMove()
    {
        return BattleEngine.pickAiMove(oppMon(), myMon(), rng);
    }

    /** Host-side: package the post-turn state for the guest. Host is "me" here. */
    public TurnState snapshot(List<String> turnLog)
    {
        TurnState s = new TurnState();
        s.hostActive = myActive;
        s.guestActive = oppActive;
        s.hostHp = hpArray(myTeam);
        s.guestHp = hpArray(oppTeam);
        s.log = new ArrayList<>(turnLog);
        s.winner = finished ? (wonByMe ? 1 : 2) : 0;
        return s;
    }

    /** Guest-side: mirror a host TurnState. Guest's "my" team is the host's guest team. */
    public List<String> applySnapshot(TurnState s)
    {
        // Derive hitsplat values from the hp deltas of the previously active mons
        int prevMyHp = myMon().hp;
        int prevOppHp = oppMon().hp;
        BattleMon prevMine = myMon();
        BattleMon prevTheirs = oppMon();
        myActive = s.guestActive;
        oppActive = s.hostActive;
        applyHp(myTeam, s.guestHp);
        applyHp(oppTeam, s.hostHp);
        prevMine.lastHitTaken = Math.max(0, prevMyHp - prevMine.hp);
        prevTheirs.lastHitTaken = Math.max(0, prevOppHp - prevTheirs.hp);
        if (s.winner != 0)
        {
            finished = true;
            wonByMe = s.winner == 2;
        }
        turn++;
        myPendingMove = null;
        List<String> log = s.log != null ? s.log : new ArrayList<>();
        fullLog.addAll(log);
        return log;
    }

    private static int[] hpArray(List<BattleMon> team)
    {
        int[] hp = new int[team.size()];
        for (int i = 0; i < team.size(); i++)
        {
            hp[i] = team.get(i).hp;
        }
        return hp;
    }

    private static void applyHp(List<BattleMon> team, int[] hp)
    {
        if (hp == null)
        {
            return;
        }
        for (int i = 0; i < team.size() && i < hp.length; i++)
        {
            team.get(i).hp = hp[i];
        }
    }

    private static int clamp(int idx, int size)
    {
        return Math.max(0, Math.min(idx, size - 1));
    }
}

