package com.osrsgo.data;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;

/** Fixed world locations: bank Heal Centers and Gertrude's breeding den. */
public final class Places
{
    public static final int HEAL_RANGE = 12;
    public static final int BREED_RANGE = 10;

    /** Gertrude's house, west of Varrock. The lady loves her animals. */
    public static final WorldPoint GERTRUDES_DEN = new WorldPoint(3151, 3412, 0);

    private static final List<WorldPoint> BANKS = Collections.unmodifiableList(Arrays.asList(
        new WorldPoint(3208, 3220, 0),  // Lumbridge castle
        new WorldPoint(3164, 3487, 0),  // Grand Exchange
        new WorldPoint(3185, 3436, 0),  // Varrock west
        new WorldPoint(3253, 3420, 0),  // Varrock east
        new WorldPoint(3094, 3491, 0),  // Edgeville
        new WorldPoint(2946, 3368, 0),  // Falador west
        new WorldPoint(3013, 3355, 0),  // Falador east
        new WorldPoint(3092, 3243, 0),  // Draynor
        new WorldPoint(3269, 3167, 0),  // Al Kharid
        new WorldPoint(2808, 3441, 0),  // Catherby
        new WorldPoint(2725, 3491, 0),  // Seers' Village
        new WorldPoint(2615, 3332, 0),  // Ardougne north
        new WorldPoint(2655, 3283, 0),  // Ardougne south
        new WorldPoint(2612, 3092, 0),  // Yanille
        new WorldPoint(3688, 3467, 0),  // Canifis
        new WorldPoint(2933, 3282, 0)   // Crafting Guild
    ));

    public static final int STORE_RANGE = 12;

    private static final List<WorldPoint> GENERAL_STORES = Collections.unmodifiableList(Arrays.asList(
        new WorldPoint(3211, 3246, 0),  // Lumbridge
        new WorldPoint(3217, 3414, 0),  // Varrock
        new WorldPoint(2955, 3388, 0),  // Falador
        new WorldPoint(3078, 3509, 0),  // Edgeville
        new WorldPoint(3315, 3180, 0),  // Al Kharid
        new WorldPoint(2946, 3216, 0),  // Rimmington
        new WorldPoint(2779, 3442, 0),  // Catherby
        new WorldPoint(1541, 3833, 0)   // Lovakengj (Zeah)
    ));

    public static boolean nearGeneralStore(WorldPoint player)
    {
        if (player == null)
        {
            return false;
        }
        for (WorldPoint store : GENERAL_STORES)
        {
            if (flatDistance(player, store) <= STORE_RANGE)
            {
                return true;
            }
        }
        return false;
    }

    /** Plane-agnostic Chebyshev distance (Lumbridge's bank is upstairs). */
    private static int flatDistance(WorldPoint a, WorldPoint b)
    {
        return Math.max(Math.abs(a.getX() - b.getX()), Math.abs(a.getY() - b.getY()));
    }

    public static boolean nearBank(WorldPoint player)
    {
        if (player == null)
        {
            return false;
        }
        for (WorldPoint bank : BANKS)
        {
            if (flatDistance(player, bank) <= HEAL_RANGE)
            {
                return true;
            }
        }
        return false;
    }

    public static boolean nearBreedingDen(WorldPoint player)
    {
        return player != null && flatDistance(player, GERTRUDES_DEN) <= BREED_RANGE;
    }

    private Places()
    {
    }
}

package com.osrsgo.data;

import com.osrsgo.model.Rarity;
import com.osrsgo.model.Species;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Raid bosses: every spawn rotation, two gyms host a Legendary raid boss.
 * Seeded from the bucket so every client sees the same raids. Beating one
 * grants big XP and catch attempts at the boss.
 */
public final class RaidData
{
    public static class Raid
    {
        public final String gymId;
        public final int speciesId;
        public final int level;

        Raid(String gymId, int speciesId, int level)
        {
            this.gymId = gymId;
            this.speciesId = speciesId;
            this.level = level;
        }
    }

    public static List<Raid> raidsFor(long bucket)
    {
        Random rng = new Random(bucket * 0xC2B2AE3D27D4EB4FL + 777);
        List<GymData.Gym> gyms = new ArrayList<>(GymData.all());
        List<Species> legendaries = new ArrayList<>();
        for (Species s : SpeciesData.all())
        {
            if (s.getRarity() == Rarity.LEGENDARY)
            {
                legendaries.add(s);
            }
        }
        List<Raid> raids = new ArrayList<>();
        for (int i = 0; i < 2 && !gyms.isEmpty(); i++)
        {
            GymData.Gym gym = gyms.remove(rng.nextInt(gyms.size()));
            Species boss = legendaries.get(rng.nextInt(legendaries.size()));
            raids.add(new Raid(gym.id, boss.getId(), 70 + rng.nextInt(16)));
        }
        return raids;
    }

    public static Raid raidAt(long bucket, String gymId)
    {
        for (Raid raid : raidsFor(bucket))
        {
            if (raid.gymId.equals(gymId))
            {
                return raid;
            }
        }
        return null;
    }

    private RaidData()
    {
    }
}

package com.osrsgo.data;

import com.osrsgo.model.MonType;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Daily research: three tasks seeded from the UTC day, identical for every
 * player. Rewards are granted the moment a task completes.
 */
public final class ResearchData
{
    public enum Kind
    {
        CATCH_ANY,
        CATCH_TYPE,
        THROW_BALLS,
        WALK_TILES,
        WIN_GYM,
        CATCH_UNCOMMON_PLUS,
        HATCH_EGGS
    }

    public static class Task
    {
        public final Kind kind;
        public final MonType type;
        public final int goal;
        public final int rewardBalls;
        public final int rewardGreatBalls;
        public final int rewardUltraBalls;
        public final int rewardXp;

        Task(Kind kind, MonType type, int goal, int rewardBalls, int rewardGreat, int rewardUltra, int rewardXp)
        {
            this.kind = kind;
            this.type = type;
            this.goal = goal;
            this.rewardBalls = rewardBalls;
            this.rewardGreatBalls = rewardGreat;
            this.rewardUltraBalls = rewardUltra;
            this.rewardXp = rewardXp;
        }

        public String describe()
        {
            switch (kind)
            {
                case CATCH_ANY: return "Catch " + goal + " wild mons";
                case CATCH_TYPE: return "Catch " + goal + " " + type.getDisplay() + " mons";
                case THROW_BALLS: return "Throw " + goal + " balls";
                case WALK_TILES: return "Walk " + goal + " tiles";
                case WIN_GYM: return "Win " + goal + " gym battle" + (goal > 1 ? "s" : "");
                case HATCH_EGGS: return "Hatch " + goal + " egg" + (goal > 1 ? "s" : "");
                default: return "Catch " + goal + " Uncommon or rarer mon" + (goal > 1 ? "s" : "");
            }
        }

        public String rewardText()
        {
            StringBuilder sb = new StringBuilder();
            if (rewardBalls > 0)
            {
                sb.append("+").append(rewardBalls).append(" balls ");
            }
            if (rewardGreatBalls > 0)
            {
                sb.append("+").append(rewardGreatBalls).append(" Great ");
            }
            if (rewardUltraBalls > 0)
            {
                sb.append("+").append(rewardUltraBalls).append(" Ultra ");
            }
            sb.append("+").append(rewardXp).append(" xp");
            return sb.toString();
        }
    }

    public static long todayUtc()
    {
        return System.currentTimeMillis() / 86_400_000L;
    }

    /** Weeks start Monday (epoch day 0 was a Thursday). */
    public static long weekUtc()
    {
        return (todayUtc() + 3) / 7;
    }

    public static long monthUtc()
    {
        java.time.YearMonth ym = java.time.YearMonth.now(java.time.ZoneOffset.UTC);
        return ym.getYear() * 12L + ym.getMonthValue();
    }

    public static List<Task> tasksFor(long day)
    {
        Random rng = new Random(day * 0x9E3779B97F4A7C15L + 42);
        List<Task> pool = new ArrayList<>();
        MonType type = MonType.values()[rng.nextInt(MonType.values().length)];
        pool.add(new Task(Kind.CATCH_ANY, null, 3 + rng.nextInt(3), 5, 0, 0, 50));
        pool.add(new Task(Kind.CATCH_TYPE, type, 2 + rng.nextInt(2), 3, 0, 0, 150));
        pool.add(new Task(Kind.THROW_BALLS, null, 5 + rng.nextInt(4), 3, 0, 0, 50));
        pool.add(new Task(Kind.WALK_TILES, null, 500 + rng.nextInt(1000), 2, 0, 0, 100));
        pool.add(new Task(Kind.WIN_GYM, null, 1, 5, 0, 0, 150));
        pool.add(new Task(Kind.CATCH_UNCOMMON_PLUS, null, 1 + rng.nextInt(2), 5, 0, 0, 100));

        List<Task> picked = new ArrayList<>();
        while (picked.size() < 3 && !pool.isEmpty())
        {
            picked.add(pool.remove(rng.nextInt(pool.size())));
        }
        return picked;
    }

    /** Two bigger weekly challenges paying Great Balls. */
    public static List<Task> weeklyTasks(long week)
    {
        Random rng = new Random(week * 0xA24BAED4963EE407L + 7);
        List<Task> pool = new ArrayList<>();
        pool.add(new Task(Kind.CATCH_ANY, null, 20 + rng.nextInt(11), 0, 3, 0, 300));
        pool.add(new Task(Kind.WALK_TILES, null, 4000 + rng.nextInt(4001), 0, 3, 0, 300));
        pool.add(new Task(Kind.WIN_GYM, null, 3 + rng.nextInt(3), 0, 3, 0, 400));
        pool.add(new Task(Kind.THROW_BALLS, null, 30 + rng.nextInt(21), 0, 2, 0, 250));
        pool.add(new Task(Kind.CATCH_UNCOMMON_PLUS, null, 5 + rng.nextInt(4), 0, 3, 0, 350));

        List<Task> picked = new ArrayList<>();
        while (picked.size() < 2 && !pool.isEmpty())
        {
            picked.add(pool.remove(rng.nextInt(pool.size())));
        }
        return picked;
    }

    /** Two monthly epics paying Ultra Balls. */
    public static List<Task> monthlyTasks(long month)
    {
        Random rng = new Random(month * 0xD6E8FEB86659FD93L + 31);
        List<Task> pool = new ArrayList<>();
        pool.add(new Task(Kind.CATCH_ANY, null, 80 + rng.nextInt(41), 0, 0, 1, 1000));
        pool.add(new Task(Kind.WALK_TILES, null, 15000 + rng.nextInt(10001), 0, 0, 1, 1000));
        pool.add(new Task(Kind.WIN_GYM, null, 10 + rng.nextInt(6), 0, 0, 1, 1200));
        pool.add(new Task(Kind.HATCH_EGGS, null, 3 + rng.nextInt(3), 0, 0, 1, 1000));
        pool.add(new Task(Kind.CATCH_UNCOMMON_PLUS, null, 15 + rng.nextInt(11), 0, 0, 1, 1100));

        List<Task> picked = new ArrayList<>();
        while (picked.size() < 2 && !pool.isEmpty())
        {
            picked.add(pool.remove(rng.nextInt(pool.size())));
        }
        return picked;
    }

    private ResearchData()
    {
    }
}

package com.osrsgo.data;

import com.osrsgo.battle.MonSpec;
import com.osrsgo.model.OwnedMon;
import java.util.ArrayList;
import java.util.List;
import java.util.Random;

/**
 * Rival NPC trainers that contest gyms when the player is not in a party.
 * Seeded from the spawn rotation bucket exactly like RaidData, so a rival's
 * name is stable for the whole rotation and shared across clients. Its
 * faction and team are NOT shared: opposingFaction depends on the local
 * player's own faction, and team levels scale with the local trainer level,
 * so only the name is guaranteed to match between two clients looking at the
 * same gym.
 */
public final class RivalData
{
    /** Deliberately title-cased and unlike RSNs, so rivals never read as players. */
    private static final String[] NAMES = {
        "Wandering Zealot", "Varrock Duelist", "Al Kharid Nomad",
        "Fremennik Raider", "Ardougne Sellsword", "Karamja Trapper",
        "Wilderness Marauder", "Kandarin Ranger", "Asgarnian Squire",
        "Misthalin Adept", "Morytania Warden", "Gnome Tactician"
    };

    private static final String[] FACTIONS = {"SARADOMIN", "ZAMORAK", "GUTHIX"};

    /** Trainer levels past this stop making rivals harder. */
    public static final int STRENGTH_CAP_LEVEL = 90;

    public static class Rival
    {
        public final String name;
        public final String faction;
        public final List<MonSpec> team;

        Rival(String name, String faction, List<MonSpec> team)
        {
            this.name = name;
            this.faction = faction;
            this.team = team;
        }
    }

    /**
     * The rival occupying one gym this rotation. The gym's own slot levels set
     * the floor so the difficulty ladder survives, and the player's level
     * scales it up until the cap.
     */
    public static Rival rivalFor(long bucket, String gymId, int trainerLevel, String playerFaction)
    {
        Random rng = new Random(seed(bucket, gymId));
        String name = NAMES[rng.nextInt(NAMES.length)];
        String faction = opposingFaction(playerFaction, rng);
        GymData.Gym gym = GymData.byId(gymId);
        List<MonSpec> team = new ArrayList<>();
        if (gym != null)
        {
            int effective = Math.min(trainerLevel, STRENGTH_CAP_LEVEL);
            for (int[] slot : gym.team)
            {
                int level = Math.min(99, slot[1] + Math.round(effective * 0.5f));
                team.add(specFor(slot[0], level));
            }
        }
        return new Rival(name, faction, team);
    }

    /** Rivals never share the player's faction, so the ally rule never blocks a reclaim. */
    private static String opposingFaction(String playerFaction, Random rng)
    {
        List<String> others = new ArrayList<>();
        for (String f : FACTIONS)
        {
            if (!f.equals(playerFaction))
            {
                others.add(f);
            }
        }
        return others.get(rng.nextInt(others.size()));
    }

    /** Reuses OwnedMon's stat math so rival stats match player stats exactly. */
    private static MonSpec specFor(int speciesId, int level)
    {
        OwnedMon m = new OwnedMon();
        m.speciesId = speciesId;
        m.level = level;
        m.ivHp = 8;
        m.ivAtk = 8;
        m.ivDef = 8;
        m.ivSpd = 8;
        return MonSpec.fromOwned(m);
    }

    private static long seed(long bucket, String gymId)
    {
        return bucket * 0x9E3779B97F4A7C15L + gymId.hashCode() * 0x100000001B3L;
    }

    /**
     * Odds that a rival takes one of the player's gyms this rotation. Rivals
     * are the stand-in for a human rival, so pressure rises with how much is
     * held, eases once the player outclasses them at 90, and eases again in a
     * party because real players take over as the threat.
     */
    public static double seizureChance(int gymsHeldByPlayer, int trainerLevel, int partyOthers)
    {
        if (gymsHeldByPlayer <= 0)
        {
            return 0.0;
        }
        double chance = Math.min(0.5, 0.05 * gymsHeldByPlayer);
        if (trainerLevel >= STRENGTH_CAP_LEVEL)
        {
            chance *= 0.2;
        }
        return chance / (1 + Math.max(0, partyOthers));
    }

    /**
     * Tribute is multiplied by party size because every party member can take
     * your gyms. This is a risk premium, not a teamwork bonus, which is why
     * stuffing a party with idle accounts does not farm anything.
     */
    public static double tributeMultiplierFor(int partyOthers)
    {
        return Math.min(2.0, 1.0 + 0.25 * Math.max(0, partyOthers));
    }

    private RivalData()
    {
    }
}

