        add(559, "Rannveig", MonType.MELEE, Rarity.COMMON, 22, 19, 15, 27);
        add(560, "Valgerd", MonType.MELEE, Rarity.COMMON, 22, 19, 15, 27);
        add(561, "Thorhild", MonType.MELEE, Rarity.COMMON, 21, 18, 14, 26);
