package com.osrsgo.gym;

import com.osrsgo.battle.MonSpec;
import java.util.List;

/** Local control state for one gym, held by whoever last claimed it. */
public class GymHolder
{
    public String gymId;
    public String holderRsn;
    public List<MonSpec> holderTeam;
    public String heldSince;
    public int defenseWins;
    public String updatedAt;
    public Integer claimedWorld;
    public String holderFaction;

    /** Holds lapse after 6h so a claim from an inactive session can't lock a gym forever. */
    public static final long HOLD_DURATION_MS = 6 * 60 * 60 * 1000L;

    public boolean isExpired()
    {
        if (heldSince == null)
        {
            return false;
        }
        try
        {
            long held = java.time.Instant.parse(heldSince).toEpochMilli();
            return System.currentTimeMillis() - held >= HOLD_DURATION_MS;
        }
        catch (Exception e)
        {
            return false;
        }
    }

    public boolean isClaimed()
    {
        return holderRsn != null && !holderRsn.isEmpty() && !isExpired();
    }

    public boolean isHeldBy(String rsn)
    {
        return isClaimed() && rsn != null && holderRsn.equalsIgnoreCase(rsn);
    }
}

package com.osrsgo.gym;

import com.osrsgo.battle.MonSpec;
import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * Gym ownership operations against the player's local map. Kept as pure
 * functions over the map so the same state can be driven from anywhere: a
 * local claim, a rival trainer seizing a gym, or a party member's broadcast.
 */
public final class LocalGyms
{
    public static GymHolder claim(Map<String, GymHolder> gyms, String gymId, String rsn,
        List<MonSpec> team, Integer world, String faction)
    {
        String now = Instant.now().toString();
        GymHolder holder = new GymHolder();
        holder.gymId = gymId;
        holder.holderRsn = rsn;
        holder.holderTeam = team;
        holder.heldSince = now;
        holder.updatedAt = now;
        holder.defenseWins = 0;
        holder.claimedWorld = world;
        holder.holderFaction = faction;
        gyms.put(gymId, holder);
        return holder;
    }

    /** The challenger beat the defenders but lost to the leader: nobody holds it. */
    public static void breakHold(Map<String, GymHolder> gyms, String gymId)
    {
        gyms.remove(gymId);
    }

    public static void recordDefense(Map<String, GymHolder> gyms, String gymId)
    {
        GymHolder holder = gyms.get(gymId);
        if (holder != null)
        {
            holder.defenseWins++;
            holder.updatedAt = Instant.now().toString();
        }
    }

    /** Drops holds past their duration, the way the server swept them lazily. */
    public static void expireStale(Map<String, GymHolder> gyms)
    {
        gyms.entrySet().removeIf(e -> e.getValue() == null || e.getValue().isExpired());
    }

    public static int heldBy(Map<String, GymHolder> gyms, String rsn)
    {
        int held = 0;
        for (GymHolder holder : gyms.values())
        {
            if (holder != null && holder.isHeldBy(rsn))
            {
                held++;
            }
        }
        return held;
    }

    /**
     * Whether a holder is protected from attack by the shared-faction rule.
     * Party members never are: two friends of one god must still be able to
     * contest a gym, or the party layer does nothing for them.
     */
    public static boolean isAlly(String playerFaction, GymHolder holder, boolean holderIsPartyMember)
    {
        return !holderIsPartyMember
            && playerFaction != null
            && holder != null
            && playerFaction.equals(holder.holderFaction);
    }

    private LocalGyms()
    {
    }
}

package com.osrsgo.harvest;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.HashMap;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * The field journal: every named, renderable NPC encountered gets recorded
 * (name, a verified id, combat level), building toward a complete GielDex.
 * Uncatalogued sightings feed the species list as new batches are added.
 */
@Slf4j
@Singleton
public class NpcHarvest
{
    public static class Seen
    {
        public String name;
        public int npcId;
        public int combat;
        public int count;
    }

    private final File file = com.osrsgo.storage.PluginFiles.file("npcdex.json");
    private final Gson gson;
    private final Map<String, Seen> byName = new HashMap<>();
    private boolean dirty;

    @Inject
    public NpcHarvest(Gson gson)
    {
        this.gson = gson;
        load();
    }

    /** Records a sighting; keeps the highest-combat variant's id per name. */
    public synchronized void record(String displayName, int npcId, int combat)
    {
        String key = displayName.toLowerCase();
        Seen seen = byName.get(key);
        if (seen == null)
        {
            seen = new Seen();
            seen.name = displayName;
            seen.npcId = npcId;
            seen.combat = combat;
            byName.put(key, seen);
            dirty = true;
        }
        else if (combat > seen.combat)
        {
            seen.npcId = npcId;
            seen.combat = combat;
            dirty = true;
        }
        seen.count++;
    }

    public synchronized int size()
    {
        return byName.size();
    }

    public synchronized java.util.List<Seen> all()
    {
        return new java.util.ArrayList<>(byName.values());
    }

    public synchronized void saveIfDirty()
    {
        if (!dirty)
        {
            return;
        }
        try
        {
            Files.write(file.toPath(), gson.toJson(byName).getBytes(StandardCharsets.UTF_8));
            dirty = false;
        }
        catch (Exception e)
        {
            log.warn("could not save npc harvest", e);
        }
    }

    private void load()
    {
        if (!file.isFile())
        {
            return;
        }
        try
        {
            Map<String, Seen> loaded = gson.fromJson(
                new String(Files.readAllBytes(file.toPath()), StandardCharsets.UTF_8),
                new TypeToken<Map<String, Seen>>()
                {
                }.getType());
            if (loaded != null)
            {
                byName.putAll(loaded);
            }
        }
        catch (Exception e)
        {
            log.warn("could not load npc harvest", e);
        }
    }
}

