package com.osrsgo.overlay;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Renders both combatants' models in the scene during a battle and smashes
 * them into each other on every resolved turn, Pokemon-style. Models sit on
 * two tiles near where the battle started; ClientTick interpolates the lunge.
 */
@Singleton
public class BattleScene
{
    private static final long CLASH_MS = 450;
    private static final long DEATH_MS = 600;
    private static final int DEATH_SINK = 420;
    private static final int FACE_EAST = 1536;
    private static final int FACE_WEST = 512;

    private final Client client;
    private final SpawnModels spawnModels;
    private final com.osrsgo.anim.AnimationLibrary animLibrary;
    private final net.runelite.client.callback.ClientThread clientThread;
    private boolean attackAnimPlaying;

    private boolean active;
    private RuneLiteObject mine;
    private RuneLiteObject theirs;
    private int mineSpecies = -1;
    private int theirsSpecies = -1;
    private WorldPoint mineWp;
    private WorldPoint theirsWp;
    private long clashStart;
    // Faint transition: the outgoing model sinks into the ground before the
    // replacement appears
    private long mineSwapAt;
    private long theirsSwapAt;
    private int pendingMineSpecies = -1;
    private int pendingTheirsSpecies = -1;
    private int mineDeathZ;
    private int theirsDeathZ;
    // Victory celebration: the winner's mon hops in place before the scene ends
    private long celebrateUntil;
    private int celebrateBaseZ;
    private static final long CELEBRATE_MS = 1500;
    // FX state read by the overlay: send-out flashes and hitsplat values
    private long mineSwitchStart;
    private long theirsSwitchStart;
    private int hitOnMine = -1;
    private int hitOnTheirs = -1;

    @Inject
    public BattleScene(Client client, SpawnModels spawnModels,
        com.osrsgo.anim.AnimationLibrary animLibrary,
        net.runelite.client.callback.ClientThread clientThread)
    {
        this.client = client;
        this.spawnModels = spawnModels;
        this.animLibrary = animLibrary;
        this.clientThread = clientThread;
    }

    /** Game tick: keeps the two models existing and correct. Client thread only. */
    public void ensure(int mySpeciesId, int oppSpeciesId, WorldPoint playerWp)
    {
        if (playerWp == null)
        {
            return;
        }
        if (!active)
        {
            int[] offs = pickStage(playerWp);
            mineWp = new WorldPoint(playerWp.getX() + offs[0], playerWp.getY() + offs[1], playerWp.getPlane());
            theirsWp = new WorldPoint(playerWp.getX() + offs[2], playerWp.getY() + offs[3], playerWp.getPlane());
            active = true;
        }
        if (mine == null)
        {
            mine = respawn(null, mySpeciesId, mineWp, FACE_EAST);
            mineSpecies = mySpeciesId;
            mineSwapAt = 0;
        }
        else if (mineSpecies != mySpeciesId)
        {
            if (mineSwapAt == 0)
            {
                mineSwapAt = System.currentTimeMillis() + DEATH_MS;
                mineDeathZ = mine.getZ();
            }
            pendingMineSpecies = mySpeciesId;
        }
        if (theirs == null)
        {
            theirs = respawn(null, oppSpeciesId, theirsWp, FACE_WEST);
            theirsSpecies = oppSpeciesId;
            theirsSwapAt = 0;
        }
        else if (theirsSpecies != oppSpeciesId)
        {
            if (theirsSwapAt == 0)
            {
                theirsSwapAt = System.currentTimeMillis() + DEATH_MS;
                theirsDeathZ = theirs.getZ();
            }
            pendingTheirsSpecies = oppSpeciesId;
        }
    }

    // Candidate stages, mine west of theirs so the fixed facings stay right:
    // north pair first (the classic), then south, further out, and finally
    // flanking the trainer as a last resort
    private static final int[][] STAGE_OFFSETS = {
        {-1, 2, 2, 2},
        {-1, -2, 2, -2},
        {-1, 3, 2, 3},
        {-1, -3, 2, -3},
        {-2, 0, 2, 0},
    };

    /** First stage whose two tiles are provably walkable (no bank booths), else the default. */
    private int[] pickStage(WorldPoint p)
    {
        for (int[] o : STAGE_OFFSETS)
        {
            WorldPoint a = new WorldPoint(p.getX() + o[0], p.getY() + o[1], p.getPlane());
            WorldPoint b = new WorldPoint(p.getX() + o[2], p.getY() + o[3], p.getPlane());
            if (Boolean.TRUE.equals(com.osrsgo.spawn.Coords.walkableInScene(client, a))
                && Boolean.TRUE.equals(com.osrsgo.spawn.Coords.walkableInScene(client, b)))
            {
                return o;
            }
        }
        return STAGE_OFFSETS[0];
    }

    private RuneLiteObject respawn(RuneLiteObject old, int speciesId, WorldPoint wp, int orientation)
    {
        if (old != null)
        {
            old.setActive(false);
        }
        Model model = spawnModels.modelForSpecies(speciesId);
        LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client,wp);
        if (model == null || lp == null)
        {
            return null;
        }
        RuneLiteObject obj = client.createRuneLiteObject();
        obj.setModel(model);
        obj.setLocation(lp, wp.getPlane());
        obj.setOrientation(orientation);
        obj.setActive(true);
        applyIdle(obj, speciesId);
        return obj;
    }

    /**
     * loadAnimation is client-thread only and throws IllegalStateException
     * anywhere else. Battle turns are driven from Swing (the move buttons), so
     * every animation swap defers to the client thread; invoke() runs inline
     * when we are already on it. A throw here used to escape mid-turn and skip
     * everything after it, silently costing gym claims and boss throws.
     */
    private void setAnim(RuneLiteObject target, int animId)
    {
        clientThread.invoke(() ->
        {
            try
            {
                target.setAnimation(client.loadAnimation(animId));
                target.setShouldLoop(true);
            }
            catch (Exception e)
            {
                // A bad learned animation is cosmetic; never fatal
            }
        });
    }

    private void applyIdle(RuneLiteObject target, int forSpecies)
    {
        Integer idle = animLibrary.idleFor(forSpecies);
        if (target != null && idle != null)
        {
            setAnim(target, idle);
        }
    }

    private void applyAttack(RuneLiteObject target, int forSpecies)
    {
        Integer attack = animLibrary.attackFor(forSpecies);
        if (target != null && attack != null)
        {
            setAnim(target, attack);
            attackAnimPlaying = true;
        }
    }

    /** The winner's mon hops in place for a moment before the scene ends. */
    public void celebrate()
    {
        if (active && mine != null)
        {
            celebrateUntil = System.currentTimeMillis() + CELEBRATE_MS;
            celebrateBaseZ = mine.getZ();
        }
    }

    public boolean isCelebrating()
    {
        return active && System.currentTimeMillis() < celebrateUntil;
    }

    /** Kicks off one lunge; both models slam toward each other and bounce back. */
    public void clash()
    {
        clash(-1, -1);
    }

    /**
     * Lunge plus hitsplat values (-1 = no splat, 0 = miss/blocked). Callers
     * settle battles right after this, so it swallows its own failures rather
     * than unwinding a turn that has already been decided.
     */
    public void clash(int damageOnMine, int damageOnTheirs)
    {
        if (!active)
        {
            return;
        }
        try
        {
            clashStart = System.currentTimeMillis();
            hitOnMine = damageOnMine;
            hitOnTheirs = damageOnTheirs;
            applyAttack(mine, mineSpecies);
            applyAttack(theirs, theirsSpecies);
        }
        catch (Exception e)
        {
            // Purely visual; the turn stands regardless
        }
    }

    public boolean isActive()
    {
        return active;
    }

    public WorldPoint getMineWp()
    {
        return mineWp;
    }

    public WorldPoint getTheirsWp()
    {
        return theirsWp;
    }

    public long getClashStart()
    {
        return clashStart;
    }

    public long getMineSwitchStart()
    {
        return mineSwitchStart;
    }

    public long getTheirsSwitchStart()
    {
        return theirsSwitchStart;
    }

    public int getHitOnMine()
    {
        return hitOnMine;
    }

    public int getHitOnTheirs()
    {
        return hitOnTheirs;
    }

    /** Client tick (~50/s): faint sink-outs first, then the lunge. Client thread only. */
    public void onClientTick()
    {
        if (!active)
        {
            return;
        }
        long now = System.currentTimeMillis();
        boolean dying = false;
        if (mineSwapAt != 0 && mine != null)
        {
            dying = true;
            if (now >= mineSwapAt)
            {
                mine = respawn(mine, pendingMineSpecies, mineWp, FACE_EAST);
                mineSpecies = pendingMineSpecies;
                mineSwitchStart = now;
                mineSwapAt = 0;
            }
            else
            {
                double t = 1 - (mineSwapAt - now) / (double) DEATH_MS;
                mine.setZ(mineDeathZ + (int) (t * DEATH_SINK));
                mine.setOrientation((mine.getOrientation() + 40) & 2047);
            }
        }
        if (theirsSwapAt != 0 && theirs != null)
        {
            dying = true;
            if (now >= theirsSwapAt)
            {
                theirs = respawn(theirs, pendingTheirsSpecies, theirsWp, FACE_WEST);
                theirsSpecies = pendingTheirsSpecies;
                theirsSwitchStart = now;
                theirsSwapAt = 0;
            }
            else
            {
                double t = 1 - (theirsSwapAt - now) / (double) DEATH_MS;
                theirs.setZ(theirsDeathZ + (int) (t * DEATH_SINK));
                theirs.setOrientation((theirs.getOrientation() + 40) & 2047);
            }
        }
        if (isCelebrating() && mine != null)
        {
            // Three little victory hops
            double t = 1 - (celebrateUntil - now) / (double) CELEBRATE_MS;
            int hop = (int) (Math.abs(Math.sin(t * Math.PI * 3)) * 40);
            mine.setZ(celebrateBaseZ - hop);
        }
        if (dying || clashStart == 0 || mine == null || theirs == null || mineWp == null)
        {
            return;
        }
        LocalPoint mineBase = com.osrsgo.spawn.Coords.toLocal(client,mineWp);
        LocalPoint theirsBase = com.osrsgo.spawn.Coords.toLocal(client,theirsWp);
        if (mineBase == null || theirsBase == null)
        {
            return;
        }
        double t = (System.currentTimeMillis() - clashStart) / (double) CLASH_MS;
        if (t >= 1)
        {
            mine.setLocation(mineBase, mineWp.getPlane());
            theirs.setLocation(theirsBase, theirsWp.getPlane());
            clashStart = 0;
            if (attackAnimPlaying)
            {
                // Swing's over: settle back into the learned idles
                applyIdle(mine, mineSpecies);
                applyIdle(theirs, theirsSpecies);
                attackAnimPlaying = false;
            }
            return;
        }
        // Peak at the midpoint of the swing: 0.4 of the gap each, so they meet
        double swing = Math.sin(Math.PI * t) * 0.4;
        int dx = theirsBase.getX() - mineBase.getX();
        int dy = theirsBase.getY() - mineBase.getY();
        mine.setLocation(new LocalPoint(
            mineBase.getX() + (int) (dx * swing), mineBase.getY() + (int) (dy * swing)), mineWp.getPlane());
        theirs.setLocation(new LocalPoint(
            theirsBase.getX() - (int) (dx * swing), theirsBase.getY() - (int) (dy * swing)), theirsWp.getPlane());
    }

    /** After a loading screen the objects are gone; rebuild on next ensure. */
    public void invalidate()
    {
        mine = null;
        theirs = null;
        mineSpecies = -1;
        theirsSpecies = -1;
        mineSwapAt = 0;
        theirsSwapAt = 0;
    }

    /** Client thread only. */
    public void stop()
    {
        if (!active)
        {
            return;
        }
        if (mine != null)
        {
            mine.setActive(false);
        }
        if (theirs != null)
        {
            theirs.setActive(false);
        }
        mine = null;
        theirs = null;
        mineSpecies = -1;
        theirsSpecies = -1;
        mineWp = null;
        theirsWp = null;
        clashStart = 0;
        mineSwapAt = 0;
        theirsSwapAt = 0;
        celebrateUntil = 0;
        active = false;
    }
}

package com.osrsgo.overlay;

import com.osrsgo.OsrsGoConfig;
import com.osrsgo.data.GymData;
import com.osrsgo.model.Rarity;
import com.osrsgo.spawn.SpawnManager;
import com.osrsgo.spawn.WildSpawn;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.geom.Ellipse2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

/**
 * Draws wild spawns (tile poly + name) and gym marks (diamond + name) in the
 * scene, plus dots for both on the minimap.
 */
public class GoOverlay extends Overlay
{
    private static final int MAX_DRAW_DISTANCE = 32;
    private static final Color GYM_OPEN = new Color(0, 220, 220);
    private static final Color GYM_MINE = new Color(255, 200, 0);
    private static final Color GYM_ENEMY = new Color(255, 90, 90);

    private final Client client;
    private final OsrsGoConfig config;
    private final SpawnManager spawnManager;
    private final com.osrsgo.OsrsGoPlugin plugin;
    private final BattleScene battleScene;
    private final java.awt.image.BufferedImage ballImage = com.osrsgo.ui.Icons.drawOrb(28);
    private final java.awt.image.BufferedImage[] tierBalls = {
        com.osrsgo.ui.Icons.tierBall(0, 28),
        com.osrsgo.ui.Icons.tierBall(1, 28),
        com.osrsgo.ui.Icons.tierBall(2, 28),
        com.osrsgo.ui.Icons.tierBall(3, 28),
        com.osrsgo.ui.Icons.tierBall(4, 28)
    };

    @Inject
    public GoOverlay(Client client, OsrsGoConfig config, SpawnManager spawnManager,
        com.osrsgo.OsrsGoPlugin plugin, BattleScene battleScene)
    {
        this.client = client;
        this.config = config;
        this.spawnManager = spawnManager;
        this.plugin = plugin;
        this.battleScene = battleScene;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public java.awt.Dimension render(Graphics2D graphics)
    {
        if (client.getLocalPlayer() == null)
        {
            return null;
        }
        // Template-space location so spawn/candy marks also work in instances
        WorldPoint player = com.osrsgo.spawn.Coords.playerLocation(client);
        if (player == null)
        {
            return null;
        }
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));

        if (config.showSpawns())
        {
            for (WildSpawn spawn : spawnManager.nearby(player, MAX_DRAW_DISTANCE))
            {
                renderSpawn(graphics, spawn);
            }
            for (com.osrsgo.spawn.SpawnManager.Candy candy : spawnManager.nearbyCandies(player, MAX_DRAW_DISTANCE))
            {
                renderCandy(graphics, candy);
            }
        }
        if (config.showGyms())
        {
            for (GymData.Gym gym : GymData.all())
            {
                if (player.distanceTo(gym.location) <= MAX_DRAW_DISTANCE * 2)
                {
                    renderGym(graphics, gym);
                }
            }
        }
        renderCatchSequence(graphics);
        renderBattleFx(graphics);
        return null;
    }

    /** HP bars, hitsplats, and send-out flashes over the two battle models. */
    private void renderBattleFx(Graphics2D graphics)
    {
        if (!battleScene.isActive())
        {
            return;
        }
        int myHp = -1;
        int myMax = 1;
        int oppHp = -1;
        int oppMax = 1;
        com.osrsgo.battle.BattleSession session = plugin.getSession();
        if (session != null)
        {
            myHp = session.myMon().hp;
            myMax = session.myMon().maxHp;
            oppHp = session.oppMon().hp;
            oppMax = session.oppMon().maxHp;
        }
        else
        {
            return;
        }
        renderBattleSide(graphics, battleScene.getMineWp(), myHp, myMax,
            battleScene.getHitOnMine(), battleScene.getMineSwitchStart());
        renderBattleSide(graphics, battleScene.getTheirsWp(), oppHp, oppMax,
            battleScene.getHitOnTheirs(), battleScene.getTheirsSwitchStart());
    }

    private void renderBattleSide(Graphics2D graphics, net.runelite.api.coords.WorldPoint wp,
        int hp, int maxHp, int hit, long switchStart)
    {
        if (wp == null)
        {
            return;
        }
        LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client,wp);
        if (lp == null)
        {
            return;
        }
        Point anchor = Perspective.getCanvasTextLocation(client, graphics, lp, "", 230);
        if (anchor == null)
        {
            return;
        }
        long now = System.currentTimeMillis();

        // Floating HP bar
        if (hp >= 0)
        {
            int barW = 34;
            int barH = 5;
            int x = anchor.getX() - barW / 2;
            int y = anchor.getY() - 8;
            graphics.setColor(new Color(120, 30, 30));
            graphics.fillRect(x, y, barW, barH);
            graphics.setColor(new Color(70, 200, 70));
            graphics.fillRect(x, y, (int) (barW * Math.max(0, Math.min(1.0, hp / (double) maxHp))), barH);
            graphics.setColor(Color.BLACK);
            graphics.setStroke(new BasicStroke(1));
            graphics.drawRect(x, y, barW, barH);
        }

        // Hitsplat riding the clash timing
        long clashElapsed = now - battleScene.getClashStart();
        if (hit >= 0 && clashElapsed > 150 && clashElapsed < 1300)
        {
            int cx = anchor.getX();
            int cy = anchor.getY() + 22;
            graphics.setColor(hit == 0 ? new Color(60, 90, 200) : new Color(180, 30, 30));
            graphics.fillOval(cx - 11, cy - 11, 22, 22);
            graphics.setColor(Color.BLACK);
            graphics.drawOval(cx - 11, cy - 11, 22, 22);
            graphics.setColor(Color.WHITE);
            graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
            String text = String.valueOf(hit);
            java.awt.FontMetrics fm = graphics.getFontMetrics();
            graphics.drawString(text, cx - fm.stringWidth(text) / 2, cy + fm.getAscent() / 2 - 2);
        }

        // Send-out flash: the Gielinor Ball bursts open where the new mon appears
        long switchElapsed = now - switchStart;
        if (switchStart > 0 && switchElapsed < 700)
        {
            double t = switchElapsed / 700.0;
            int cx = anchor.getX();
            int cy = anchor.getY() + 20;
            graphics.drawImage(ballImage, cx - 14, cy - 14, null);
            int r = (int) (8 + t * 34);
            graphics.setColor(new Color(255, 255, 255, (int) (200 * (1 - t))));
            graphics.setStroke(new BasicStroke(3));
            graphics.drawOval(cx - r, cy - r, r * 2, r * 2);
            graphics.setColor(new Color(255, 220, 60, (int) (160 * (1 - t))));
            graphics.drawOval(cx - r / 2, cy - r / 2, r, r);
        }
    }

    /** The Gielinor Ball throw: arc to the tile, three shakes, then the verdict. */
    private void renderCatchSequence(Graphics2D graphics)
    {
        com.osrsgo.spawn.CatchSequence seq = plugin.getActiveCatch();
        if (seq == null)
        {
            return;
        }
        LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client,seq.spawn.location);
        if (lp == null)
        {
            return;
        }
        Point target = Perspective.getCanvasTextLocation(client, graphics, lp, "", 0);
        if (target == null)
        {
            return;
        }
        long elapsed = seq.elapsed();
        java.awt.image.BufferedImage ball =
            tierBalls[Math.max(0, Math.min(seq.ballTier, tierBalls.length - 1))];
        int tx = target.getX();
        int ty = target.getY();

        if (elapsed < com.osrsgo.spawn.CatchSequence.THROW_MS)
        {
            double t = elapsed / (double) com.osrsgo.spawn.CatchSequence.THROW_MS;
            int sx = client.getCanvasWidth() / 2;
            int sy = client.getCanvasHeight() - 40;
            int x = (int) (sx + (tx - sx) * t);
            int y = (int) (sy + (ty - sy) * t - Math.sin(Math.PI * t) * 140);
            drawBall(graphics, ball, x, y, t * 720);
            return;
        }

        long shakeElapsed = elapsed - com.osrsgo.spawn.CatchSequence.THROW_MS;
        if (shakeElapsed < com.osrsgo.spawn.CatchSequence.SHAKE_MS)
        {
            double t = shakeElapsed / (double) com.osrsgo.spawn.CatchSequence.SHAKE_MS;
            double angle = Math.sin(t * Math.PI * 6) * 24;
            drawBall(graphics, ball, tx, ty, angle);
            return;
        }

        long resultElapsed = elapsed - com.osrsgo.spawn.CatchSequence.THROW_MS
            - com.osrsgo.spawn.CatchSequence.SHAKE_MS;
        double t = Math.min(1.0, resultElapsed / (double) com.osrsgo.spawn.CatchSequence.RESULT_MS);
        String verdict;
        Color verdictColor;
        if (seq.outcome == com.osrsgo.spawn.CatchSequence.Outcome.CAUGHT)
        {
            drawBall(graphics, ball, tx, ty, 0);
            // Expanding capture ring
            int r = (int) (10 + t * 30);
            graphics.setColor(new Color(255, 220, 60, (int) (200 * (1 - t))));
            graphics.setStroke(new BasicStroke(3));
            graphics.drawOval(tx - r, ty - r, r * 2, r * 2);
            verdict = "Gotcha!";
            verdictColor = new Color(120, 255, 120);
        }
        else
        {
            // Ball pops open: halves fly apart
            int off = (int) (t * 18);
            graphics.drawImage(ball.getSubimage(0, 0, 28, 14), tx - 14, ty - 14 - off, null);
            graphics.drawImage(ball.getSubimage(0, 14, 28, 14), tx - 14, ty + off, null);
            verdict = seq.outcome == com.osrsgo.spawn.CatchSequence.Outcome.FLED ? "It fled!" : "Broke free!";
            verdictColor = new Color(255, 120, 100);
        }
        graphics.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 14));
        graphics.setColor(Color.BLACK);
        java.awt.FontMetrics fm = graphics.getFontMetrics();
        int textX = tx - fm.stringWidth(verdict) / 2;
        int textY = ty - 34 - (int) (t * 10);
        graphics.drawString(verdict, textX + 1, textY + 1);
        graphics.setColor(verdictColor);
        graphics.drawString(verdict, textX, textY);
    }

    private void drawBall(Graphics2D graphics, java.awt.image.BufferedImage ball, int x, int y, double angleDeg)
    {
        java.awt.geom.AffineTransform old = graphics.getTransform();
        graphics.translate(x, y);
        graphics.rotate(Math.toRadians(angleDeg));
        graphics.drawImage(ball, -ball.getWidth() / 2, -ball.getHeight() / 2, null);
        graphics.setTransform(old);
    }

    private static final Color SHINY_GOLD = new Color(255, 215, 60);
    private static final Color CANDY_PURPLE = new Color(190, 110, 250);
    private final java.awt.image.BufferedImage candyImage = com.osrsgo.ui.Icons.candy(22);

    /** A rare candy on the ground: purple tile, floating sweet, sparkles. */
    private void renderCandy(Graphics2D graphics, com.osrsgo.spawn.SpawnManager.Candy candy)
    {
        LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client, candy.location);
        if (lp == null)
        {
            return;
        }
        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly != null)
        {
            OverlayUtil.renderPolygon(graphics, poly, CANDY_PURPLE);
        }
        Point text = Perspective.getCanvasTextLocation(client, graphics, lp, "RARE CANDY", 40);
        if (text != null)
        {
            OverlayUtil.renderTextLocation(graphics, text, "RARE CANDY", CANDY_PURPLE);
            graphics.drawImage(candyImage, text.getX() - 34, text.getY() - 16, null);
        }
        renderShinySparkles(graphics, lp, candy.key.hashCode());
        renderMinimapDot(graphics, lp, CANDY_PURPLE);
    }

    private void renderSpawn(Graphics2D graphics, WildSpawn spawn)
    {
        LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client,spawn.location);
        if (lp == null)
        {
            return;
        }
        Rarity rarity = spawn.species().getRarity();
        Color color = spawn.shiny ? SHINY_GOLD : rarity.getColor();

        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly != null)
        {
            OverlayUtil.renderPolygon(graphics, poly, color);
        }
        String label = (spawn.shiny ? "SHINY " : "") + spawn.species().getName() + " (lvl " + spawn.level + ")";
        Point text = Perspective.getCanvasTextLocation(client, graphics, lp, label, 40);
        if (text != null)
        {
            OverlayUtil.renderTextLocation(graphics, text, label, color);
            if (spawn.shiny)
            {
                drawStar(graphics, text.getX() - 12, text.getY() - 5, 5);
            }
        }
        if (spawn.shiny)
        {
            renderShinySparkles(graphics, lp, spawn.key.hashCode());
        }
        renderMinimapDot(graphics, lp, color);
    }

    /**
     * Twinkling sparkles orbiting a shiny's model. Time-driven so they
     * animate every frame; each spawn gets its own phase from its key.
     */
    private void renderShinySparkles(Graphics2D graphics, LocalPoint lp, int phaseSeed)
    {
        Point anchor = Perspective.getCanvasTextLocation(client, graphics, lp, "", 90);
        if (anchor == null)
        {
            return;
        }
        double t = System.currentTimeMillis() / 1000.0 + (phaseSeed & 0xFF) / 37.0;
        for (int i = 0; i < 3; i++)
        {
            double angle = t * 1.6 + i * (Math.PI * 2 / 3);
            int radius = 16 + (int) (Math.sin(t * 2.3 + i) * 5);
            int sx = anchor.getX() + (int) (Math.cos(angle) * radius);
            int sy = anchor.getY() + (int) (Math.sin(angle) * radius * 0.55);
            // Twinkle: each sparkle fades in and out on its own beat
            double twinkle = (Math.sin(t * 3.1 + i * 2.1) + 1) / 2;
            if (twinkle < 0.15)
            {
                continue;
            }
            int size = 3 + (int) (twinkle * 3);
            java.awt.Composite old = graphics.getComposite();
            graphics.setComposite(java.awt.AlphaComposite.getInstance(
                java.awt.AlphaComposite.SRC_OVER, (float) Math.min(1.0, 0.35 + twinkle * 0.65)));
            drawStar(graphics, sx, sy, size);
            graphics.setComposite(old);
        }
    }

    /** Small four-point sparkle used to mark shiny spawns. */
    private void drawStar(Graphics2D graphics, int cx, int cy, int r)
    {
        Polygon star = new Polygon(
            new int[]{cx, cx + r / 3, cx + r, cx + r / 3, cx, cx - r / 3, cx - r, cx - r / 3},
            new int[]{cy - r, cy - r / 3, cy, cy + r / 3, cy + r, cy + r / 3, cy, cy - r / 3},
            8);
        graphics.setColor(SHINY_GOLD);
        graphics.fillPolygon(star);
        graphics.setColor(Color.BLACK);
        graphics.setStroke(new BasicStroke(1));
        graphics.drawPolygon(star);
    }

    private void renderGym(Graphics2D graphics, GymData.Gym gym)
    {
        LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client,gym.location);
        if (lp == null)
        {
            return;
        }
        Color color;
        String suffix = "";
        if (!config.gymControl())
        {
            // Gym control is off: no holder state applies, so this is the
            // gym's pre-feature form, colored purely by whether its badge is
            // already earned (same fallback the panel uses in this state)
            color = plugin.hasBadge(gym.badge) ? GYM_MINE : GYM_OPEN;
        }
        else
        {
            switch (plugin.gymOwnership(gym.id))
            {
                case MINE:
                    color = GYM_MINE;
                    suffix = " (yours)";
                    break;
                case ENEMY:
                    color = GYM_ENEMY;
                    com.osrsgo.gym.GymHolder holder = plugin.getGymHolder(gym.id);
                    suffix = holder != null ? " (" + holder.holderRsn + ")" : "";
                    break;
                case UNCLAIMED:
                default:
                    color = GYM_OPEN;
                    break;
            }
        }

        Polygon poly = Perspective.getCanvasTilePoly(client, lp);
        if (poly != null)
        {
            graphics.setColor(color);
            graphics.setStroke(new BasicStroke(2));
            graphics.drawPolygon(poly);
            // Diamond mark centered on the tile
            java.awt.Rectangle b = poly.getBounds();
            int cx = b.x + b.width / 2;
            int cy = b.y + b.height / 2;
            int r = Math.max(6, b.width / 4);
            Polygon diamond = new Polygon(
                new int[]{cx, cx + r, cx, cx - r},
                new int[]{cy - r, cy, cy + r, cy},
                4);
            graphics.drawPolygon(diamond);
        }
        String label = gym.name + suffix;
        Point text = Perspective.getCanvasTextLocation(client, graphics, lp, label, 60);
        if (text != null)
        {
            OverlayUtil.renderTextLocation(graphics, text, label, color);
        }
        renderMinimapDot(graphics, lp, color);
    }

    private void renderMinimapDot(Graphics2D graphics, LocalPoint lp, Color color)
    {
        Point mini = Perspective.localToMinimap(client, lp);
        if (mini == null)
        {
            return;
        }
        graphics.setColor(color);
        graphics.fill(new Ellipse2D.Float(mini.getX() - 2, mini.getY() - 2, 4, 4));
        graphics.setColor(Color.BLACK);
        graphics.draw(new Ellipse2D.Float(mini.getX() - 2, mini.getY() - 2, 4, 4));
    }
}

package com.osrsgo.overlay;

import com.osrsgo.data.NpcModelData;
import com.osrsgo.spawn.WildSpawn;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;

/**
 * Renders actual NPC models on spawn tiles via RuneLiteObjects. Everything
 * runs on the client thread from the game tick. Models are merged from the
 * NPC composition's model ids and cached per species; spawns without a
 * loadable model silently keep just the tile overlay.
 */
@Slf4j
@Singleton
public class SpawnModels
{
    private final Client client;
    private final com.osrsgo.anim.AnimationLibrary animLibrary;
    private final Map<String, RuneLiteObject> live = new HashMap<>();
    private final Map<String, Integer> baseZ = new HashMap<>();
    private final Map<Integer, Model> modelCache = new HashMap<>();
    private final Set<Integer> failedSpecies = new HashSet<>();

    @Inject
    public SpawnModels(Client client, com.osrsgo.anim.AnimationLibrary animLibrary)
    {
        this.client = client;
        this.animLibrary = animLibrary;
    }

    /**
     * Syncs scene objects to the current spawn set. Client thread only.
     * Model merging is expensive, so at most ONE new model is built per sync;
     * a rotation dumping many fresh species spreads its builds over ticks
     * instead of spiking one.
     */
    public void sync(List<WildSpawn> spawns, boolean enabled)
    {
        boolean builtOne = false;
        Set<String> wanted = new HashSet<>();
        if (enabled)
        {
            for (WildSpawn spawn : spawns)
            {
                if (spawn.location.getPlane() != client.getPlane())
                {
                    continue;
                }
                LocalPoint lp = com.osrsgo.spawn.Coords.toLocal(client,spawn.location);
                if (lp == null)
                {
                    continue;
                }
                wanted.add(spawn.key);
                RuneLiteObject existing = live.get(spawn.key);
                if (existing != null)
                {
                    existing.setLocation(lp, spawn.location.getPlane());
                    // A pose learned after this object was created applies
                    // retroactively: bobbing keys are the unposed ones
                    if (baseZ.containsKey(spawn.key))
                    {
                        Integer learnt = animLibrary.idleFor(spawn.speciesId);
                        if (learnt != null)
                        {
                            try
                            {
                                existing.setAnimation(client.loadAnimation(learnt));
                                existing.setShouldLoop(true);
                                existing.setZ(baseZ.remove(spawn.key));
                            }
                            catch (Exception e)
                            {
                                // A rogue learned anim must never wedge the tick
                                baseZ.remove(spawn.key);
                            }
                        }
                    }
                    continue;
                }
                int modelKey = modelKey(spawn.speciesId, spawn.shiny);
                Model model = modelCache.get(modelKey);
                if (model == null)
                {
                    if (builtOne || failedSpecies.contains(modelKey))
                    {
                        // Not yet built; leave for a later tick
                        wanted.remove(spawn.key);
                        continue;
                    }
                    model = modelFor(spawn.speciesId, spawn.shiny);
                    builtOne = true;
                }
                if (model == null)
                {
                    wanted.remove(spawn.key);
                    continue;
                }
                RuneLiteObject obj = client.createRuneLiteObject();
                obj.setModel(model);
                obj.setLocation(lp, spawn.location.getPlane());
                obj.setActive(true);
                live.put(spawn.key, obj);
                Integer idle = animLibrary.idleFor(spawn.speciesId);
                boolean posed = false;
                if (idle != null)
                {
                    try
                    {
                        // A real learned idle animation beats the synthetic bob
                        obj.setAnimation(client.loadAnimation(idle));
                        obj.setShouldLoop(true);
                        posed = true;
                    }
                    catch (Exception e)
                    {
                        // Fall back to the bob rather than wedge the tick
                    }
                }
                if (!posed)
                {
                    baseZ.put(spawn.key, obj.getZ());
                }
            }
        }
        live.entrySet().removeIf(entry ->
        {
            if (!wanted.contains(entry.getKey()))
            {
                entry.getValue().setActive(false);
                baseZ.remove(entry.getKey());
                return true;
            }
            return false;
        });
    }

    /** Client tick: a gentle breathing bob, phase-shifted per spawn. Client thread only. */
    public void onClientTick(boolean enabled)
    {
        if (!enabled || live.isEmpty())
        {
            return;
        }
        long now = System.currentTimeMillis();
        for (Map.Entry<String, RuneLiteObject> entry : live.entrySet())
        {
            Integer base = baseZ.get(entry.getKey());
            if (base == null)
            {
                continue;
            }
            double phase = (entry.getKey().hashCode() & 0xFFFF) / 65535.0 * Math.PI * 2;
            int bob = (int) ((Math.sin(now / 700.0 + phase) + 1) * 3);
            entry.getValue().setZ(base - bob);
        }
    }

    private static int modelKey(int speciesId, boolean shiny)
    {
        return speciesId | (shiny ? 1 << 20 : 0);
    }

    private Model modelFor(int speciesId)
    {
        return modelFor(speciesId, false);
    }

    private Model modelFor(int speciesId, boolean shiny)
    {
        int key = modelKey(speciesId, shiny);
        Model cached = modelCache.get(key);
        if (cached != null)
        {
            return cached;
        }
        if (failedSpecies.contains(key))
        {
            return null;
        }
        try
        {
            int npcId = NpcModelData.npcIdFor(speciesId);
            if (npcId < 0)
            {
                failedSpecies.add(key);
                return null;
            }
            NPCComposition comp = client.getNpcDefinition(npcId);
            if (comp == null || comp.getModels() == null || comp.getModels().length == 0)
            {
                failedSpecies.add(key);
                return null;
            }
            int[] ids = comp.getModels();
            ModelData[] parts = new ModelData[ids.length];
            for (int i = 0; i < ids.length; i++)
            {
                ModelData loaded = client.loadModelData(ids[i]);
                if (loaded == null)
                {
                    failedSpecies.add(key);
                    return null;
                }
                // loadModelData returns a shared cached instance; recoloring it
                // in place would bleed palette swaps into every other species
                // built from the same base model
                parts[i] = loaded.cloneColors();
            }
            ModelData merged = client.mergeModels(parts);
            // Palette swaps: chromatic dragons, wizard robes, etc. share one
            // base model and differ only by these recolor tables. Without them
            // every dragon renders red and every mage looks identical.
            short[] find = comp.getColorToReplace();
            short[] replaceWith = comp.getColorToReplaceWith();
            if (find != null && replaceWith != null)
            {
                for (int i = 0; i < find.length && i < replaceWith.length; i++)
                {
                    merged = merged.recolor(find[i], replaceWith[i]);
                }
            }
            // NPC definitions carry non-default scales (128 = 100%); without
            // them some species render comically over- or under-sized
            if (comp.getWidthScale() != 128 || comp.getHeightScale() != 128)
            {
                merged = merged.scale(comp.getWidthScale(), comp.getHeightScale(), comp.getWidthScale());
            }
            if (shiny)
            {
                merged = goldify(merged);
            }
            Model model = merged.light();
            modelCache.put(key, model);
            return model;
        }
        catch (Exception e)
        {
            log.warn("model build failed for species {} (shiny={})", speciesId, shiny, e);
            failedSpecies.add(key);
            return null;
        }
    }

    /**
     * The shiny variant: every face color hue-shifted to gold with boosted
     * saturation, luminance preserved so shading survives. Jagex HSL packs
     * hue in bits 10-15, saturation 7-9, luminance 0-6.
     */
    private static ModelData goldify(ModelData model)
    {
        // Write the face-color array directly: recolor() depends on exact
        // color matching and missed faces on some models. Every face golds,
        // no exceptions.
        ModelData cloned = model.cloneColors();
        short[] faceColors = cloned.getFaceColors();
        for (int i = 0; i < faceColors.length; i++)
        {
            int hsl = faceColors[i] & 0xFFFF;
            int sat = (hsl >> 7) & 0x7;
            int lum = hsl & 0x7F;
            // Lift near-black faces so dark armor visibly golds; keep the
            // original shading gradient everywhere brighter
            int goldLum = Math.min(127, Math.max(lum, 25 + lum / 2));
            faceColors[i] = (short) ((9 << 10) | (Math.min(7, sat + 3) << 7) | goldLum);
        }
        return cloned;
    }

    /**
     * Diagnostic sweep: tries to build one species' model from scratch and
     * says exactly where it fails. Clears any cached failure first so a
     * retry is honest. Client thread only.
     */
    public String diagnose(int speciesId, boolean shiny)
    {
        int key = modelKey(speciesId, shiny);
        failedSpecies.remove(key);
        modelCache.remove(key);
        int npcId = NpcModelData.npcIdFor(speciesId);
        if (npcId < 0)
        {
            return "no npc mapping";
        }
        NPCComposition comp;
        try
        {
            comp = client.getNpcDefinition(npcId);
        }
        catch (Exception e)
        {
            return "composition threw " + e.getClass().getSimpleName() + " (npc " + npcId + ")";
        }
        if (comp == null)
        {
            return "composition null (npc " + npcId + ")";
        }
        if (comp.getModels() == null || comp.getModels().length == 0)
        {
            return "composition has NO models (npc " + npcId + " '" + comp.getName() + "')";
        }
        for (int id : comp.getModels())
        {
            if (client.loadModelData(id) == null)
            {
                return "model part " + id + " failed to load (npc " + npcId + " '" + comp.getName() + "')";
            }
        }
        try
        {
            Model model = modelFor(speciesId, shiny);
            return model != null ? null : "build returned null (npc " + npcId + " '" + comp.getName() + "')";
        }
        catch (Exception e)
        {
            return "build threw " + e.getClass().getSimpleName() + ": " + e.getMessage()
                + " (npc " + npcId + " '" + comp.getName() + "')";
        }
    }

    /**
     * Scene reloads (loading screens, region transitions) destroy scene
     * objects; drop the stale handles so the next sync recreates everything.
     */
    public void invalidate()
    {
        live.clear();
        baseZ.clear();
    }

    /** Merged, lit model for a species; null when unavailable. */
    public Model modelForSpecies(int speciesId)
    {
        return modelFor(speciesId);
    }

    /** Shiny-aware variant for the buddy follower. */
    public Model modelForSpecies(int speciesId, boolean shiny)
    {
        return modelFor(speciesId, shiny);
    }

    /** Client thread only. */
    public void clear()
    {
        for (RuneLiteObject obj : live.values())
        {
            obj.setActive(false);
        }
        live.clear();
        modelCache.clear();
    }
}

