package com.osrsgo.spawn;

import com.osrsgo.model.OwnedMon;

/**
 * A catch attempt in flight: the outcome is rolled up front, but applied only
 * after the overlay finishes animating the ball throw and shakes.
 */
public class CatchSequence
{
    public enum Outcome
    {
        CAUGHT,
        BROKE_FREE,
        FLED
    }

    public static final long THROW_MS = 700;
    public static final long SHAKE_MS = 1500;
    public static final long RESULT_MS = 900;
    public static final long TOTAL_MS = THROW_MS + SHAKE_MS + RESULT_MS;

    public final WildSpawn spawn;
    public final Outcome outcome;
    public final OwnedMon pendingMon;
    public final int ballTier;
    public final long startMs;

    public CatchSequence(WildSpawn spawn, Outcome outcome, OwnedMon pendingMon, int ballTier)
    {
        this.spawn = spawn;
        this.outcome = outcome;
        this.pendingMon = pendingMon;
        this.ballTier = ballTier;
        this.startMs = System.currentTimeMillis();
    }

    public long elapsed()
    {
        return System.currentTimeMillis() - startMs;
    }

    public boolean finished()
    {
        return elapsed() >= TOTAL_MS;
    }
}

package com.osrsgo.spawn;

import net.runelite.api.Client;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/**
 * Spawn logic runs in real-map (template) coordinates everywhere, including
 * inside instances (raids, POH). Instanced scenes shift the client into a
 * private coordinate space; these helpers translate both directions so the
 * deterministic shared world keeps working there. Everyone in the same
 * instance shares the same template chunks, so they still see the same mons.
 */
public final class Coords
{
    /** The player's location in template space (plain world location outside instances). */
    public static WorldPoint playerLocation(Client client)
    {
        if (client.getLocalPlayer() == null)
        {
            return null;
        }
        LocalPoint local = client.getLocalPlayer().getLocalLocation();
        if (client.isInInstancedRegion() && local != null)
        {
            return WorldPoint.fromLocalInstance(client, local);
        }
        return client.getLocalPlayer().getWorldLocation();
    }

    /**
     * Scene-local point for a template-space world point, instance-aware.
     * Inside instances only a same-plane match renders (no cross-floor
     * ghosts); null when the tile isn't in the current scene.
     */
    public static LocalPoint toLocal(Client client, WorldPoint wp)
    {
        if (wp == null)
        {
            return null;
        }
        if (client.isInInstancedRegion())
        {
            for (WorldPoint p : WorldPoint.toLocalInstance(client, wp))
            {
                if (p.getPlane() != client.getPlane())
                {
                    continue;
                }
                LocalPoint lp = LocalPoint.fromWorld(client, p);
                if (lp != null)
                {
                    return lp;
                }
            }
            return null;
        }
        return LocalPoint.fromWorld(client, wp);
    }

    /**
     * Flags that leave a tile standable. A wall on one edge, or something
     * blocking line of sight across it, still lets a creature occupy the tile.
     */
    private static final int STANDABLE_MASK =
        net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_NORTH
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_EAST
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_SOUTH
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST
        | net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_WEST
        | net.runelite.api.CollisionDataFlag.BLOCK_LINE_OF_SIGHT_NORTH
        | net.runelite.api.CollisionDataFlag.BLOCK_LINE_OF_SIGHT_EAST
        | net.runelite.api.CollisionDataFlag.BLOCK_LINE_OF_SIGHT_SOUTH
        | net.runelite.api.CollisionDataFlag.BLOCK_LINE_OF_SIGHT_WEST
        | net.runelite.api.CollisionDataFlag.BLOCK_LINE_OF_SIGHT_FULL;

    /**
     * Whether a creature can stand on a tile carrying these collision flags.
     *
     * This is an ALLOWLIST on purpose. It used to be a blocklist of the flags
     * RuneLite happens to name, which meant any bit the game client sets that
     * the API has no constant for read as open floor. Dungeon rock carries
     * 0x40000000, which RuneLite does not name, so monsters were placed inside
     * walls. Treating every unrecognised bit as solid fixes that bit and any
     * other the client may set.
     */
    public static boolean walkableFlags(int flags)
    {
        return (flags & ~STANDABLE_MASK) == 0;
    }

    /**
     * Walkability of a template-space tile on the player's current plane.
     * Null when the tile or its collision data isn't in the scene.
     */
    public static Boolean walkableInScene(Client client, WorldPoint wp)
    {
        LocalPoint lp = toLocal(client, wp);
        net.runelite.api.CollisionData[] maps = client.getCollisionMaps();
        int plane = client.getPlane();
        if (lp == null || maps == null || plane < 0 || plane >= maps.length || maps[plane] == null)
        {
            return null;
        }
        int flags = maps[plane].getFlags()[lp.getSceneX()][lp.getSceneY()];
        return walkableFlags(flags);
    }

    private Coords()
    {
    }
}

package com.osrsgo.spawn;

import com.osrsgo.model.Rarity;
import com.osrsgo.model.Species;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;

import com.osrsgo.data.SpeciesData;

/**
 * Deterministic wild spawns with no server: every client seeds the same RNG
 * from (regionId, 15-minute epoch bucket), so all players see identical spawns.
 * Spawns rotate when the bucket rolls over.
 */
public class SpawnManager
{
    public static final long BUCKET_MILLIS = 10 * 60 * 1000L;
    private static final int CATCH_RANGE = 5;
    // Fixed for everyone: density is part of the shared world, not a preference.
    // 4 felt crowded once real 3D models were standing on every spawn tile.
    private static final int SPAWNS_PER_REGION = 2;

    /** A Rare Candy on the ground: deterministic like spawns, scooped by walking onto it. */
    public static class Candy
    {
        public final String key;
        public WorldPoint location;
        public final int[] candX;
        public final int[] candY;
        public boolean placementVerified;

        Candy(String key, WorldPoint location, int[] candX, int[] candY)
        {
            this.key = key;
            this.location = location;
            this.candX = candX;
            this.candY = candY;
        }
    }

    // Roughly one candy per ~60 region-waves: genuinely rare, shared by all
    private static final int CANDY_ONE_IN = 60;

    private final Map<String, WildSpawn> spawns = new LinkedHashMap<>();
    private final Map<String, Candy> candies = new LinkedHashMap<>();
    private final Set<String> takenCandies = new HashSet<>();
    private final Set<String> removedKeys = new HashSet<>();
    private final Map<Integer, Long> regionBuckets = new HashMap<>();
    private int[] currentRegions = new int[0];
    private final List<Species> speciesPool = SpeciesData.all();

    /**
     * Each region's rotation clock is phase-shifted by a hash of its id, so
     * fresh spawns ripple in continuously instead of the whole world flipping
     * at once. Pure function of region id: every client agrees.
     */
    private static long regionOffset(int regionId)
    {
        return Math.floorMod(regionId * 2654435761L, BUCKET_MILLIS);
    }

    private static long bucketFor(int regionId, long now)
    {
        return (now + regionOffset(regionId)) / BUCKET_MILLIS;
    }

    /**
     * Recomputes the spawn table when any region's wave or the loaded regions
     * change. Returns true if new spawns appeared (a wave rotated).
     */
    public boolean update(Client client)
    {
        if (client.getLocalPlayer() == null)
        {
            return false;
        }
        int[] regions = client.getMapRegions();
        if (regions == null)
        {
            return false;
        }
        long now = System.currentTimeMillis();
        boolean regionsChanged = !Arrays.equals(regions, currentRegions);
        boolean anyRotated = false;
        for (int regionId : regions)
        {
            Long known = regionBuckets.get(regionId);
            if (known != null && known != bucketFor(regionId, now))
            {
                anyRotated = true;
                break;
            }
        }
        if (!regionsChanged && !anyRotated)
        {
            // Every tick: it's a few hundred array reads, and it caps how
            // long a mis-placed mon can be seen standing on water
            revalidatePlacements(client);
            return false;
        }
        currentRegions = regions.clone();
        rebuild(client, now);
        if (removedKeys.size() > 2000)
        {
            // Keys are bucket-unique so stale entries can never resurrect;
            // this only bounds memory over a long session
            removedKeys.clear();
        }
        return anyRotated;
    }

    // Candidate tiles rolled per spawn slot. The count is FIXED so every
    // client consumes the same random stream regardless of what its collision
    // data says; only the pick among candidates uses collision (static map
    // data, identical on every client that has the tile loaded). 20 keeps
    // cave regions (mostly wall) from despawning everything.
    private static final int TILE_CANDIDATES = 20;

    private void rebuild(Client client, long now)
    {
        // Scene crossings rebuild the table; spawns whose key survives keep
        // their object (and thus their settled position) so nothing teleports
        Map<String, WildSpawn> previous = new HashMap<>(spawns);
        Map<String, Candy> previousCandies = new HashMap<>(candies);
        spawns.clear();
        candies.clear();
        regionBuckets.clear();
        int perRegion = SPAWNS_PER_REGION;
        for (int regionId : currentRegions)
        {
            long bucket = bucketFor(regionId, now);
            regionBuckets.put(regionId, bucket);
            Random rng = new Random(seed(regionId, bucket));
            int baseX = (regionId >> 8) << 6;
            int baseY = (regionId & 0xFF) << 6;
            for (int i = 0; i < perRegion; i++)
            {
                int[] candX = new int[TILE_CANDIDATES];
                int[] candY = new int[TILE_CANDIDATES];
                for (int c = 0; c < TILE_CANDIDATES; c++)
                {
                    candX[c] = baseX + rng.nextInt(64);
                    candY[c] = baseY + rng.nextInt(64);
                }
                Species species = rollSpecies(rng, bucket, candX[0], candY[0]);
                Rarity r = species.getRarity();
                int level = r.getMinLevel() + rng.nextInt(r.getMaxLevel() - r.getMinLevel() + 1);
                // Same seeded stream, so every client agrees on which spawns shine
                boolean shiny = rng.nextInt(64) == 0;

                int x = candX[0];
                int y = candY[0];
                boolean verified = false;
                for (int c = 0; c < TILE_CANDIDATES; c++)
                {
                    if (Boolean.TRUE.equals(walkable(client, candX[c], candY[c])))
                    {
                        x = candX[c];
                        y = candY[c];
                        verified = true;
                        break;
                    }
                }

                String key = regionId + ":" + bucket + ":" + i;
                WildSpawn existing = previous.get(key);
                if (existing != null)
                {
                    spawns.put(key, existing);
                }
                else if (!removedKeys.contains(key))
                {
                    WildSpawn spawn = new WildSpawn(key, species.getId(), level,
                        new WorldPoint(x, y, 0), shiny, candX, candY);
                    spawn.placementVerified = verified;
                    spawns.put(key, spawn);
                }
            }

            // The rare candy roll rides the same seeded stream, so everyone
            // sees the same sweets on the same tiles
            if (rng.nextInt(CANDY_ONE_IN) == 0)
            {
                int[] cx = new int[TILE_CANDIDATES];
                int[] cy = new int[TILE_CANDIDATES];
                for (int c = 0; c < TILE_CANDIDATES; c++)
                {
                    cx[c] = baseX + rng.nextInt(64);
                    cy[c] = baseY + rng.nextInt(64);
                }
                String candyKey = "candy:" + regionId + ":" + bucket;
                Candy existing = previousCandies.get(candyKey);
                if (existing != null)
                {
                    candies.put(candyKey, existing);
                }
                else if (!takenCandies.contains(candyKey))
                {
                    int px = cx[0];
                    int py = cy[0];
                    boolean ok = false;
                    for (int c = 0; c < TILE_CANDIDATES; c++)
                    {
                        if (Boolean.TRUE.equals(walkable(client, cx[c], cy[c])))
                        {
                            px = cx[c];
                            py = cy[c];
                            ok = true;
                            break;
                        }
                    }
                    Candy candy = new Candy(candyKey, new WorldPoint(px, py, 0), cx, cy);
                    candy.placementVerified = ok;
                    candies.put(candyKey, candy);
                }
            }
        }
    }

    /** Candies on the player's plane within range, nearest first. */
    public List<Candy> nearbyCandies(WorldPoint player, int maxDistance)
    {
        List<Candy> result = new ArrayList<>();
        for (Candy c : candies.values())
        {
            if (player.getPlane() == c.location.getPlane() && player.distanceTo(c.location) <= maxDistance)
            {
                result.add(c);
            }
        }
        result.sort((a, b) -> Integer.compare(player.distanceTo(a.location), player.distanceTo(b.location)));
        return result;
    }

    /** Every live candy, for diagnostics. */
    public java.util.Collection<Candy> allCandies()
    {
        return candies.values();
    }

    /** Removes a picked-up candy for the rest of its rotation. */
    public void takeCandy(String key)
    {
        takenCandies.add(key);
        candies.remove(key);
        if (takenCandies.size() > 500)
        {
            takenCandies.clear();
        }
    }

    /**
     * Spawns placed before their tile's collision data was loaded (scene-edge
     * regions) may sit on water or walls. Once the data is available, hop them
     * to their first provably walkable candidate. Deterministic across clients
     * because the candidate list is part of the seeded roll.
     */
    private void revalidatePlacements(Client client)
    {
        java.util.Iterator<Candy> cit = candies.values().iterator();
        while (cit.hasNext())
        {
            Candy candy = cit.next();
            if (candy.placementVerified)
            {
                continue;
            }
            Boolean current = walkable(client, candy.location.getX(), candy.location.getY());
            if (current == null)
            {
                continue;
            }
            if (current)
            {
                candy.placementVerified = true;
                continue;
            }
            boolean moved = false;
            for (int c = 0; c < candy.candX.length; c++)
            {
                Boolean w = walkable(client, candy.candX[c], candy.candY[c]);
                if (Boolean.TRUE.equals(w))
                {
                    candy.location = new WorldPoint(candy.candX[c], candy.candY[c], 0);
                    candy.placementVerified = true;
                    moved = true;
                    break;
                }
            }
            if (!moved)
            {
                // Its tile is provably blocked (water, walls) and no candidate
                // rescues it: a sweet nobody can reach is just clutter
                cit.remove();
            }
        }

        java.util.Iterator<WildSpawn> it = spawns.values().iterator();
        while (it.hasNext())
        {
            WildSpawn spawn = it.next();
            if (spawn.placementVerified)
            {
                continue;
            }
            Boolean current = walkable(client, spawn.location.getX(), spawn.location.getY());
            if (current == null)
            {
                continue;
            }
            if (current)
            {
                spawn.placementVerified = true;
                continue;
            }
            boolean moved = false;
            for (int c = 0; c < spawn.candX.length; c++)
            {
                Boolean w = walkable(client, spawn.candX[c], spawn.candY[c]);
                if (Boolean.TRUE.equals(w))
                {
                    spawn.location = new WorldPoint(spawn.candX[c], spawn.candY[c], 0);
                    spawn.placementVerified = true;
                    moved = true;
                    break;
                }
            }
            if (!moved)
            {
                // The current tile is provably blocked (water, walls) and no
                // candidate rescues it. Sweep the whole region for a real
                // floor tile; the sweep skips unknown tiles safely, so an
                // off-scene candidate must not veto it (that veto left mons
                // standing on rivers).
                relocateOrDespawn(client, spawn, it);
            }
        }
    }

    /**
     * Deterministic last resort: scan the spawn's whole 64x64 region from a
     * seeded start point and take the first walkable tile. Collision is static
     * map data, so every client that reaches this point picks the same tile.
     * Despawns only when the entire region is provably blocked (open water).
     */
    private void relocateOrDespawn(Client client, WildSpawn spawn, java.util.Iterator<WildSpawn> it)
    {
        int regionId;
        try
        {
            regionId = Integer.parseInt(spawn.key.substring(0, spawn.key.indexOf(':')));
        }
        catch (Exception e)
        {
            return;
        }
        int baseX = (regionId >> 8) << 6;
        int baseY = (regionId & 0xFF) << 6;
        int start = ((spawn.candX[0] - baseX) & 63) * 64 + ((spawn.candY[0] - baseY) & 63);
        boolean anyUnknown = false;
        for (int step = 0; step < 4096; step++)
        {
            int idx = (start + step) & 4095;
            int x = baseX + (idx >> 6);
            int y = baseY + (idx & 63);
            Boolean w = walkable(client, x, y);
            if (w == null)
            {
                anyUnknown = true;
            }
            else if (w)
            {
                spawn.location = new WorldPoint(x, y, 0);
                spawn.placementVerified = true;
                return;
            }
        }
        if (!anyUnknown)
        {
            removedKeys.add(spawn.key);
            it.remove();
        }
    }

    /**
     * True/false when the tile's collision data is loaded in the current
     * scene, null when unknown (outside the scene or no collision map).
     */

    private static Boolean walkable(Client client, int worldX, int worldY)
    {
        net.runelite.api.CollisionData[] maps = client.getCollisionMaps();
        if (maps == null)
        {
            return null;
        }
        if (client.isInInstancedRegion())
        {
            // Spawn tiles are template coords; find where this instance placed
            // that chunk (if it did) and read collision there
            for (WorldPoint p : WorldPoint.toLocalInstance(client, new WorldPoint(worldX, worldY, 0)))
            {
                int sceneX = p.getX() - client.getBaseX();
                int sceneY = p.getY() - client.getBaseY();
                if (sceneX < 0 || sceneX >= 104 || sceneY < 0 || sceneY >= 104
                    || p.getPlane() < 0 || p.getPlane() >= maps.length || maps[p.getPlane()] == null)
                {
                    continue;
                }
                int flags = maps[p.getPlane()].getFlags()[sceneX][sceneY];
                return Coords.walkableFlags(flags);
            }
            return null;
        }
        int sceneX = worldX - client.getBaseX();
        int sceneY = worldY - client.getBaseY();
        if (sceneX < 0 || sceneX >= 104 || sceneY < 0 || sceneY >= 104)
        {
            return null;
        }
        if (maps[0] == null)
        {
            return null;
        }
        int flags = maps[0].getFlags()[sceneX][sceneY];
        return Coords.walkableFlags(flags);
    }

    private static long seed(int regionId, long bucket)
    {
        long h = 1469598103934665603L;
        h = (h ^ regionId) * 1099511628211L;
        h = (h ^ bucket) * 1099511628211L;
        return h;
    }

    private Species rollSpecies(Random rng, long bucket, int x, int y)
    {
        com.osrsgo.data.BiomeData.Biome biome = com.osrsgo.data.BiomeData.biomeAt(x, y);
        com.osrsgo.data.BiomeData.DangerZone zone = com.osrsgo.data.BiomeData.dangerZoneAt(x, y);
        // Both derive from the region's own bucket so clients that rebuild at
        // different wall times still roll identical spawns
        int spotlightId = spotlightSpeciesId(bucket);
        boolean night = com.osrsgo.data.BiomeData.isNight(bucket * BUCKET_MILLIS);
        int total = 0;
        for (Species s : speciesPool)
        {
            total += spawnWeight(s, biome, zone, spotlightId, night);
        }
        if (total <= 0)
        {
            return speciesPool.get(0);
        }
        int roll = rng.nextInt(total);
        for (Species s : speciesPool)
        {
            roll -= spawnWeight(s, biome, zone, spotlightId, night);
            if (roll < 0)
            {
                return s;
            }
        }
        return speciesPool.get(0);
    }

    public boolean isNightNow()
    {
        return com.osrsgo.data.BiomeData.isNight(System.currentTimeMillis());
    }

    private static final int SPOTLIGHT_MULTIPLIER = 5;
    private static final int COMMUNITY_SPOTLIGHT_MULTIPLIER = 12;

    /**
     * Community Hour: Saturdays 20:00-21:00 UTC, same for every player.
     * Spotlight surges, catches pay double XP, balls turn up twice as fast.
     */
    public static boolean isCommunityHour()
    {
        java.time.ZonedDateTime now = java.time.ZonedDateTime.now(java.time.ZoneOffset.UTC);
        return now.getDayOfWeek() == java.time.DayOfWeek.SATURDAY && now.getHour() == 20;
    }

    /**
     * Every rotation spotlights one non-boss species worldwide with surged
     * spawns. Seeded from the bucket alone, so every client agrees.
     */
    public int spotlightSpeciesId(long bucket)
    {
        List<Species> eligible = new ArrayList<>();
        for (Species s : speciesPool)
        {
            if (s.getRarity() != Rarity.EPIC && s.getRarity() != Rarity.LEGENDARY)
            {
                eligible.add(s);
            }
        }
        Random rng = new Random(seed(999331, bucket));
        return eligible.get(rng.nextInt(eligible.size())).getId();
    }

    /** The current rotation's spotlight species id. */
    public int currentSpotlightId()
    {
        return spotlightSpeciesId(System.currentTimeMillis() / BUCKET_MILLIS);
    }

    private static int spawnWeight(Species s, com.osrsgo.data.BiomeData.Biome biome,
        com.osrsgo.data.BiomeData.DangerZone zone, int spotlightId, boolean night)
    {
        int weight = s.getRarity().getSpawnWeight()
            * com.osrsgo.data.BiomeData.weightMultiplier(s.getId(), biome)
            * com.osrsgo.data.BiomeData.nightMultiplier(s.getId(), night);
        if (zone != null)
        {
            weight *= zone.rarityMultiplier(s.getRarity());
        }
        if (s.getId() == spotlightId)
        {
            weight *= isCommunityHour() ? COMMUNITY_SPOTLIGHT_MULTIPLIER : SPOTLIGHT_MULTIPLIER;
        }
        return weight;
    }

    /** Spawns on the player's plane sorted by distance, nearest first. */
    public List<WildSpawn> nearby(WorldPoint player, int maxDistance)
    {
        List<WildSpawn> result = new ArrayList<>();
        for (WildSpawn s : spawns.values())
        {
            if (player.getPlane() == s.location.getPlane() && player.distanceTo(s.location) <= maxDistance)
            {
                result.add(s);
            }
        }
        result.sort((a, b) -> Integer.compare(player.distanceTo(a.location), player.distanceTo(b.location)));
        return result;
    }

    public boolean inCatchRange(WorldPoint player, WildSpawn spawn)
    {
        return inCatchRange(player, spawn, CATCH_RANGE);
    }

    public boolean inCatchRange(WorldPoint player, WildSpawn spawn, int range)
    {
        return player.getPlane() == spawn.location.getPlane()
            && player.distanceTo(spawn.location) <= range;
    }

    /** Removes a spawn for the rest of the current rotation (caught or fled). */
    public void remove(WildSpawn spawn)
    {
        removedKeys.add(spawn.key);
        spawns.remove(spawn.key);
    }

    public WildSpawn byKey(String key)
    {
        return spawns.get(key);
    }

    /** Millis until the soonest wave among the loaded regions rotates. */
    public long millisUntilRotation()
    {
        long now = System.currentTimeMillis();
        long soonest = BUCKET_MILLIS - (now % BUCKET_MILLIS);
        for (int regionId : currentRegions)
        {
            soonest = Math.min(soonest, BUCKET_MILLIS - ((now + regionOffset(regionId)) % BUCKET_MILLIS));
        }
        return soonest;
    }

    public void reset()
    {
        spawns.clear();
        candies.clear();
        takenCandies.clear();
        removedKeys.clear();
        regionBuckets.clear();
        currentRegions = new int[0];
    }
}

package com.osrsgo.spawn;

import com.osrsgo.data.SpeciesData;
import com.osrsgo.model.Species;
import net.runelite.api.coords.WorldPoint;

public class WildSpawn
{
    public final String key;
    public final int speciesId;
    public final int level;
    public final boolean shiny;
    // Position can refine to a walkable candidate once collision data loads
    public WorldPoint location;
    public final int[] candX;
    public final int[] candY;
    public boolean placementVerified;
    public int failedAttempts;

    public WildSpawn(String key, int speciesId, int level, WorldPoint location, boolean shiny,
        int[] candX, int[] candY)
    {
        this.key = key;
        this.speciesId = speciesId;
        this.level = level;
        this.location = location;
        this.shiny = shiny;
        this.candX = candX;
        this.candY = candY;
    }

    public Species species()
    {
        return SpeciesData.byId(speciesId);
    }
}

package com.osrsgo.storage;

import com.osrsgo.model.OwnedMon;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

public class PlayerProfile
{
    public List<OwnedMon> mons = new ArrayList<>();
    public List<Integer> teamIndices = new ArrayList<>();
    // Three switchable team loadouts; teamIndices is always the ACTIVE one
    public int activeTeamSlot;
    public List<List<Integer>> savedTeams = new ArrayList<>();
    public Set<String> badges = new LinkedHashSet<>();
    public Set<Integer> seenSpecies = new LinkedHashSet<>();
    public Set<Integer> caughtSpecies = new LinkedHashSet<>();
    public int trainerXp;
    // Field default doubles as the starter grant: Gson leaves it when a stored
    // profile predates the ball economy
    public int balls = 15;
    public int greatBalls;
    public int superBalls;
    public int ultraBalls;
    public int masterBalls;
    public long tilesWalked;
    public int ballProgress;
    public int xpBallProgress;
    public Integer buddyIndex;
    public int buddyProgress;
    public List<com.osrsgo.model.Egg> eggs = new ArrayList<>();
    public Stats stats = new Stats();
    // Legacy per-species essence; folded into tierEssence on first touch
    public java.util.Map<Integer, Integer> essence = new java.util.HashMap<>();
    // Essence pools by rarity tier (COMMON..LEGENDARY): any mon of a tier
    // feeds the pool, any same-tier evolve/level spends from it
    public java.util.Map<String, Integer> tierEssence = new java.util.HashMap<>();
    // Gym control state, held locally. Keyed by gym id.
    public java.util.Map<String, com.osrsgo.gym.GymHolder> gyms = new java.util.HashMap<>();
    public String faction;
    public int berries;
    public int berryProgress;
    public long researchDay = -1;
    public int[] researchProgress = new int[3];
    public boolean[] researchDone = new boolean[3];
    public long researchWeek = -1;
    public int[] weeklyProgress = new int[2];
    public boolean[] weeklyDone = new boolean[2];
    public long researchMonth = -1;
    public int[] monthlyProgress = new int[2];
    public boolean[] monthlyDone = new boolean[2];
    public Set<String> earnedMedals = new LinkedHashSet<>();
    // Nearby-tab target filter: only these species show when non-empty
    public Set<Integer> huntTargets = new LinkedHashSet<>();
    // Raid bosses already challenged this rotation ("bucket:gymId"), pruned each rotation
    public Set<String> raidAttempts = new LinkedHashSet<>();
    // Purple sweets scooped off the ground; each levels a mon by one
    public int rareCandies;
    // Universal essence from releasing shinies; substitutes for any species essence
    public int shinyEssence;
    // Bumped on every save; lets a session notice another client writing
    public long saveCounter;

    public static String tierOf(int speciesId)
    {
        com.osrsgo.model.Species sp = com.osrsgo.data.SpeciesData.byId(speciesId);
        return sp != null ? sp.getRarity().name() : com.osrsgo.model.Rarity.COMMON.name();
    }

    /** Folds any legacy per-species essence into the tier pools. Idempotent. */
    public void migrateEssence()
    {
        if (essence.isEmpty())
        {
            return;
        }
        for (java.util.Map.Entry<Integer, Integer> e : essence.entrySet())
        {
            tierEssence.merge(tierOf(e.getKey()), e.getValue(), Integer::sum);
        }
        essence.clear();
    }

    public int essenceOf(int speciesId)
    {
        migrateEssence();
        Integer amount = tierEssence.get(tierOf(speciesId));
        return amount != null ? amount : 0;
    }

    public void addEssence(int speciesId, int amount)
    {
        migrateEssence();
        tierEssence.merge(tierOf(speciesId), amount, Integer::sum);
    }

    /** Lifetime counters, local-only. */
    public static class Stats
    {
        public int ballsFound;
        public int ballsThrown;
        public int catches;
        public int shinyCatches;
        public int breakFrees;
        public int flees;
        public int gymWins;
        public int gymLosses;
        public int gymsCaptured;
        public int pvpWins;
        public int pvpLosses;
        public int breeds;
        public int eggsHatched;
        public int evolutions;
        public int berriesFound;
        public int candiesFound;
        public int berriesUsed;
        public int trades;
        public int raidWins;
        public int researchCompleted;
    }

    public int trainerLevel()
    {
        return 1 + (int) Math.floor(Math.sqrt(trainerXp / 100.0));
    }

    public int xpIntoLevel()
    {
        int lvl = trainerLevel();
        return trainerXp - xpAtLevel(lvl);
    }

    public int xpForNextLevel()
    {
        int lvl = trainerLevel();
        return xpAtLevel(lvl + 1) - xpAtLevel(lvl);
    }

    private static int xpAtLevel(int level)
    {
        int n = level - 1;
        return n * n * 100;
    }

    public List<OwnedMon> team()
    {
        List<OwnedMon> team = new ArrayList<>();
        for (Integer idx : teamIndices)
        {
            if (idx != null && idx >= 0 && idx < mons.size())
            {
                team.add(mons.get(idx));
            }
        }
        return team;
    }
}

package com.osrsgo.storage;

import java.io.File;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.RuneLite;

/**
 * Every file this plugin reads or writes lives under a single directory of
 * its own inside the RuneLite folder. Nothing here ever touches a path
 * outside {@link #dir()}.
 *
 * Earlier versions scattered six entries across the RuneLite folder itself,
 * each merely prefixed with the plugin name. {@link #migrateLegacyFiles()}
 * moves those into place once, so a player keeps the animations and NPC
 * records they built up rather than starting the collection over.
 */
@Slf4j
public final class PluginFiles
{
    private static final String DIR_NAME = "gielinor-safari";

    /** Old name, new name. Both loose files and directories. */
    private static final String[][] LEGACY = {
        {"osrsgo-anims.json", "anims.json"},
        {"osrsgo-npcdex.json", "npcdex.json"},
        {"osrsgo-profile-backup.json", "profile-backup.json"},
        {"osrsgo-profile-prerestore.json", "profile-prerestore.json"},
        {"osrsgo-images", "images"},
        {"osrsgo-cards", "cards"},
    };

    /** The plugin's own directory, created if it does not exist yet. */
    public static File dir()
    {
        File dir = new File(RuneLite.RUNELITE_DIR, DIR_NAME);
        if (!dir.isDirectory() && !dir.mkdirs())
        {
            log.warn("could not create the Gielinor Safari directory at {}", dir);
        }
        return dir;
    }

    /** A file inside the plugin directory. */
    public static File file(String name)
    {
        return new File(dir(), name);
    }

    /** A subdirectory inside the plugin directory, created if missing. */
    public static File subDir(String name)
    {
        File sub = new File(dir(), name);
        if (!sub.isDirectory() && !sub.mkdirs())
        {
            log.warn("could not create {}", sub);
        }
        return sub;
    }

    /**
     * Moves anything left in the old locations into the plugin directory.
     * Only ever moves onto a name that is still free, so a file already in
     * the new layout always wins and running this twice does nothing.
     */
    public static void migrateLegacyFiles()
    {
        for (String[] pair : LEGACY)
        {
            File old = new File(RuneLite.RUNELITE_DIR, pair[0]);
            if (!old.exists())
            {
                continue;
            }
            File moved = new File(dir(), pair[1]);
            if (moved.exists())
            {
                continue;
            }
            try
            {
                if (!old.renameTo(moved))
                {
                    log.debug("could not move {} into the plugin directory", pair[0]);
                }
            }
            catch (Exception e)
            {
                log.debug("could not move {} into the plugin directory", pair[0], e);
            }
        }
    }

    private PluginFiles()
    {
    }
}

package com.osrsgo.storage;

import com.google.gson.Gson;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.config.ConfigManager;

@Slf4j
@Singleton
public class ProfileStore
{
    private static final String GROUP = "osrsgo";
    private static final String KEY = "profile";
    private static final String SIG_KEY = "profileSig";
    private static final String BACKUP_KEY = "profileBackup";

    private final ConfigManager configManager;
    private final Gson gson;
    private boolean tamperDetected;
    // The save counter we last wrote or loaded; a mismatch on save means
    // another client (an alt on the same RuneLite profile) is also playing
    private long lastKnownCounter = -1;
    private volatile boolean conflictDetected;

    /** True once when another writer has been detected; resets on read. */
    public boolean consumeConflict()
    {
        boolean c = conflictDetected;
        conflictDetected = false;
        return c;
    }

    private static final java.util.regex.Pattern COUNTER_PATTERN =
        java.util.regex.Pattern.compile("\"saveCounter\"\\s*:\\s*(\\d+)");

    private long storedCounter()
    {
        String json = configManager.getConfiguration(GROUP, KEY);
        if (json == null)
        {
            return -1;
        }
        java.util.regex.Matcher m = COUNTER_PATTERN.matcher(json);
        return m.find() ? Long.parseLong(m.group(1)) : 0;
    }

    @Inject
    public ProfileStore(ConfigManager configManager, Gson gson)
    {
        this.configManager = configManager;
        this.gson = gson;
    }

    /** True when the last load found a profile whose signature didn't match. */
    public boolean wasTampered()
    {
        return tamperDetected;
    }

    public synchronized PlayerProfile load()
    {
        try
        {
            String json = configManager.getConfiguration(GROUP, KEY);
            if (json != null && !json.isEmpty())
            {
                String sig = configManager.getConfiguration(GROUP, SIG_KEY);
                // A mismatched signature is flagged but NEVER wipes: a save
                // race once cost a whole collection. Data survival outranks
                // the anti-cheat ceiling of a client-side game.
                if (sig != null && !sig.isEmpty() && !sign(json).equals(sig))
                {
                    log.warn("Gielinor Safari profile signature mismatch; accepting data anyway");
                    tamperDetected = true;
                }
                PlayerProfile profile = gson.fromJson(json, PlayerProfile.class);
                if (profile != null)
                {
                    lastKnownCounter = profile.saveCounter;
                    normalize(profile);
                    return profile;
                }
            }
        }
        catch (Exception e)
        {
            log.warn("Failed to load Gielinor Safari profile, starting fresh", e);
        }
        return new PlayerProfile();
    }

    /**
     * Fills in every collection a profile is expected to have and clamps the
     * fields that must sit in range. Profiles written by older versions are
     * missing keys entirely, and Gson leaves those null. Both load paths run
     * this: the restore command promotes a backup straight to the live
     * profile, so an unnormalised backup would put those nulls into play.
     */
    public static void normalize(PlayerProfile profile)
    {
        if (profile.mons == null)
        {
            profile.mons = new java.util.ArrayList<>();
        }
        if (profile.teamIndices == null)
        {
            profile.teamIndices = new java.util.ArrayList<>();
        }
        if (profile.badges == null)
        {
            profile.badges = new java.util.LinkedHashSet<>();
        }
        if (profile.seenSpecies == null)
        {
            profile.seenSpecies = new java.util.LinkedHashSet<>();
        }
        if (profile.caughtSpecies == null)
        {
            profile.caughtSpecies = new java.util.LinkedHashSet<>();
        }
        // Backfill the registry for mons caught before it existed
        if (profile.mons != null)
        {
            for (com.osrsgo.model.OwnedMon m : profile.mons)
            {
                profile.seenSpecies.add(m.speciesId);
                profile.caughtSpecies.add(m.speciesId);
            }
        }
        if (profile.eggs == null)
        {
            profile.eggs = new java.util.ArrayList<>();
        }
        if (profile.stats == null)
        {
            profile.stats = new PlayerProfile.Stats();
        }
        if (profile.essence == null)
        {
            profile.essence = new java.util.HashMap<>();
        }
        if (profile.tierEssence == null)
        {
            profile.tierEssence = new java.util.HashMap<>();
        }
        if (profile.gyms == null)
        {
            profile.gyms = new java.util.HashMap<>();
        }
        if (profile.researchProgress == null || profile.researchProgress.length != 3)
        {
            profile.researchProgress = new int[3];
        }
        if (profile.researchDone == null || profile.researchDone.length != 3)
        {
            profile.researchDone = new boolean[3];
        }
        if (profile.earnedMedals == null)
        {
            profile.earnedMedals = new java.util.LinkedHashSet<>();
        }
        if (profile.weeklyProgress == null || profile.weeklyProgress.length != 2)
        {
            profile.weeklyProgress = new int[2];
        }
        if (profile.weeklyDone == null || profile.weeklyDone.length != 2)
        {
            profile.weeklyDone = new boolean[2];
        }
        if (profile.monthlyProgress == null || profile.monthlyProgress.length != 2)
        {
            profile.monthlyProgress = new int[2];
        }
        if (profile.monthlyDone == null || profile.monthlyDone.length != 2)
        {
            profile.monthlyDone = new boolean[2];
        }
        if (profile.savedTeams == null)
        {
            profile.savedTeams = new java.util.ArrayList<>();
        }
        while (profile.savedTeams.size() < 3)
        {
            profile.savedTeams.add(new java.util.ArrayList<>());
        }
        if (profile.activeTeamSlot < 0 || profile.activeTeamSlot > 2)
        {
            profile.activeTeamSlot = 0;
        }
        // Starter ball grant, and migration for pre-economy profiles
        if (profile.balls <= 0 && profile.tilesWalked == 0)
        {
            profile.balls = 15;
        }
    }

    public synchronized void save(PlayerProfile profile)
    {
        long stored = storedCounter();
        if (lastKnownCounter >= 0 && stored >= 0 && stored != lastKnownCounter)
        {
            // Someone else wrote since we did; we still win (last writer),
            // but the player deserves to know their sessions are fighting
            conflictDetected = true;
        }
        profile.saveCounter = Math.max(stored, lastKnownCounter) + 1;
        lastKnownCounter = profile.saveCounter;
        String json = gson.toJson(profile);
        configManager.setConfiguration(GROUP, KEY, json);
        configManager.setConfiguration(GROUP, SIG_KEY, sign(json));
        maybeBackup(profile, json);
    }

    private static int monCount(String json)
    {
        if (json == null)
        {
            return -1;
        }
        // Must be a key unique to owned mons: GymHolder.holderTeam is a
        // List<MonSpec>, and MonSpec.speciesId serializes under the exact
        // same "speciesId" key, so gym defender teams would otherwise inflate
        // this count and let a backup with fewer real mons get overwritten
        int count = 0;
        int idx = 0;
        while ((idx = json.indexOf("\"caughtAt\"", idx)) != -1)
        {
            count++;
            idx += 10;
        }
        return count;
    }

    /**
     * A second copy that only ever grows: the backup is overwritten only when
     * the current profile has at least as many mons as the backup does, so a
     * wiped or shrunken profile can never destroy it. Also mirrored to a
     * plain file for hand recovery.
     */
    private void maybeBackup(PlayerProfile profile, String json)
    {
        try
        {
            String backup = configManager.getConfiguration(GROUP, BACKUP_KEY);
            if (monCount(json) >= monCount(backup))
            {
                configManager.setConfiguration(GROUP, BACKUP_KEY, json);
                java.io.File file = PluginFiles.file("profile-backup.json");
                java.nio.file.Files.write(file.toPath(),
                    json.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            }
        }
        catch (Exception e)
        {
            log.warn("profile backup failed", e);
        }
    }

    /**
     * Writes the profile to osrsgo-profile-prerestore.json before a restore
     * replaces it. A restore is destructive by design, so this file is the
     * only route back if the backup turns out to be older or thinner than the
     * player expected. It is deliberately not read by anything: recovery is a
     * manual act, so a bad restore cannot be compounded by an automatic one.
     */
    public synchronized void snapshotBeforeRestore(PlayerProfile profile)
    {
        try
        {
            java.io.File file = PluginFiles.file("profile-prerestore.json");
            java.nio.file.Files.write(file.toPath(),
                gson.toJson(profile).getBytes(java.nio.charset.StandardCharsets.UTF_8));
        }
        catch (Exception e)
        {
            log.warn("pre-restore snapshot failed", e);
        }
    }

    /** The backup profile, or null when none exists. */
    public synchronized PlayerProfile loadBackup()
    {
        try
        {
            String json = configManager.getConfiguration(GROUP, BACKUP_KEY);
            if (json != null && !json.isEmpty())
            {
                PlayerProfile backup = gson.fromJson(json, PlayerProfile.class);
                if (backup != null)
                {
                    // The restore command makes this the live profile outright,
                    // so it has to come back as complete as a normal load
                    normalize(backup);
                    return backup;
                }
            }
        }
        catch (Exception e)
        {
            log.warn("could not load backup profile", e);
        }
        return null;
    }

    /**
     * HMAC over the profile JSON. Stops config-file editing; a determined
     * decompiler can recover the key, which is the accepted ceiling for a
     * client-side game. The key is assembled at runtime to avoid being a
     * single greppable string literal.
     */
    private String sign(String json)
    {
        try
        {
            byte[] key = keyMaterial();
            javax.crypto.Mac mac = javax.crypto.Mac.getInstance("HmacSHA256");
            mac.init(new javax.crypto.spec.SecretKeySpec(key, "HmacSHA256"));
            byte[] digest = mac.doFinal(json.getBytes(java.nio.charset.StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder();
            for (byte b : digest)
            {
                hex.append(String.format("%02x", b));
            }
            return hex.toString();
        }
        catch (Exception e)
        {
            log.warn("profile signing unavailable", e);
            return "";
        }
    }

    private static byte[] keyMaterial()
    {
        long[] parts = {0x4765727472756465L, 0x6C6F766573686572L, 0x6B697474656E7321L, 0x6F737273676F7631L};
        byte[] key = new byte[parts.length * 8];
        for (int i = 0; i < parts.length; i++)
        {
            for (int j = 0; j < 8; j++)
            {
                key[i * 8 + j] = (byte) ((parts[i] >>> (56 - j * 8)) ^ (0x5A + i * 7 + j));
            }
        }
        return key;
    }
}

package com.osrsgo.ui;

import com.osrsgo.model.Species;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.HashMap;
import java.util.Map;

/** All plugin imagery is drawn in code so the jar ships no resources. */
public final class Icons
{
    private static final Map<Integer, BufferedImage> SPECIES_CACHE = new HashMap<>();
    private static BufferedImage pokeball;
    private static BufferedImage gymMark;

    public static synchronized BufferedImage pokeball()
    {
        if (pokeball == null)
        {
            pokeball = drawOrb(24);
        }
        return pokeball;
    }

    public static BufferedImage drawOrb(int size)
    {
        return drawBall(size, new Color(220, 60, 60), Color.WHITE);
    }

    /** Tier colors: 0 Gielinor red, 1 Great blue, 2 Super silver, 3 Ultra gold/black, 4 Master purple. */
    public static BufferedImage tierBall(int tier, int size)
    {
        switch (tier)
        {
            case 1: return drawBall(size, new Color(60, 110, 230), Color.WHITE);
            case 2: return drawBall(size, new Color(190, 195, 205), Color.WHITE);
            case 3: return drawBall(size, new Color(240, 190, 40), new Color(45, 45, 50));
            case 4: return drawBall(size, new Color(150, 70, 210), Color.WHITE);
            default: return drawBall(size, new Color(220, 60, 60), Color.WHITE);
        }
    }

    /**
     * An enchanted rune orb: single-color glossy sphere with an etched rune
     * diamond. Deliberately nothing like a certain other franchise's
     * red-and-white capture device.
     */
    private static BufferedImage drawBall(int size, Color base, Color sigil)
    {
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int m = Math.max(1, size / 12);
        int d = size - 2 * m;
        g.setPaint(new java.awt.GradientPaint(m, m, base.brighter(), m, m + d, base.darker()));
        g.fillOval(m, m, d, d);
        g.setColor(new Color(0, 0, 0, 170));
        g.setStroke(new BasicStroke(Math.max(1f, size / 24f)));
        g.drawOval(m, m, d, d);
        int r = Math.max(2, d / 4);
        int cx = size / 2;
        int cy = size / 2;
        g.setColor(sigil);
        g.setStroke(new BasicStroke(Math.max(1f, size / 16f)));
        g.drawPolygon(
            new int[]{cx, cx + r, cx, cx - r},
            new int[]{cy - r, cy, cy + r, cy},
            4);
        g.drawLine(cx, cy - r, cx, cy + r);
        g.setColor(new Color(255, 255, 255, 110));
        g.fillOval(m + d / 5, m + d / 6, d / 4, d / 5);
        g.dispose();
        return img;
    }

    public static synchronized BufferedImage gymMark()
    {
        if (gymMark != null)
        {
            return gymMark;
        }
        BufferedImage img = new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setColor(new Color(0, 200, 200));
        int[] xs = {8, 15, 8, 1};
        int[] ys = {1, 8, 15, 8};
        g.fillPolygon(xs, ys, 4);
        g.setColor(Color.BLACK);
        g.drawPolygon(xs, ys, 4);
        g.setColor(Color.WHITE);
        g.fillOval(6, 6, 4, 4);
        g.dispose();
        gymMark = img;
        return img;
    }

    /** 24px medallion: rarity-colored disc, type-colored ring, species initials. */
    public static synchronized BufferedImage speciesIcon(Species species)
    {
        BufferedImage cached = SPECIES_CACHE.get(species.getId());
        if (cached != null)
        {
            return cached;
        }
        int size = 24;
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        Color rarity = species.getRarity().getColor();
        g.setColor(new Color(rarity.getRed() / 3, rarity.getGreen() / 3, rarity.getBlue() / 3));
        g.fillOval(1, 1, size - 2, size - 2);
        g.setColor(species.getType().getColor());
        g.setStroke(new BasicStroke(2f));
        g.drawOval(2, 2, size - 4, size - 4);
        g.setColor(rarity);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        String initials = initialsOf(species.getName());
        java.awt.FontMetrics fm = g.getFontMetrics();
        g.drawString(initials, (size - fm.stringWidth(initials)) / 2, (size + fm.getAscent() - fm.getDescent()) / 2);
        g.dispose();
        SPECIES_CACHE.put(species.getId(), img);
        return img;
    }

    private static BufferedImage candy;

    /** The purple sweet: wrapped-candy silhouette, unmistakable at a glance. */
    public static synchronized BufferedImage candy(int size)
    {
        if (candy != null && candy.getWidth() == size)
        {
            return candy;
        }
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int cx = size / 2;
        int cy = size / 2;
        int r = (int) (size * 0.28);
        int w = (int) (size * 0.22);
        // Wrapper twists
        g.setColor(new Color(150, 70, 210));
        g.fillPolygon(new int[]{cx - r, cx - r - w, cx - r - w}, new int[]{cy, cy - w, cy + w}, 3);
        g.fillPolygon(new int[]{cx + r, cx + r + w, cx + r + w}, new int[]{cy, cy - w, cy + w}, 3);
        // Body
        g.setPaint(new java.awt.GradientPaint(cx, cy - r, new Color(190, 110, 250),
            cx, cy + r, new Color(120, 40, 180)));
        g.fillOval(cx - r, cy - r, r * 2, r * 2);
        g.setColor(new Color(0, 0, 0, 150));
        g.setStroke(new BasicStroke(Math.max(1f, size / 20f)));
        g.drawOval(cx - r, cy - r, r * 2, r * 2);
        // Gloss
        g.setColor(new Color(255, 255, 255, 130));
        g.fillOval(cx - r / 2, cy - r + r / 4, r / 2, r / 3);
        g.dispose();
        candy = img;
        return img;
    }

    private static BufferedImage berry;

    public static synchronized BufferedImage berry(int size)
    {
        if (berry != null && berry.getWidth() == size)
        {
            return berry;
        }
        BufferedImage img = new BufferedImage(size, size, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = img.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        int d = (int) (size * 0.62);
        g.setColor(new Color(200, 40, 70));
        g.fillOval(1, size - d - 1, d, d);
        g.fillOval(size - d - 1, size - d - 1, d, d);
        g.setColor(new Color(90, 170, 60));
        g.fillOval(size / 2 - 2, 1, 5, 4);
        g.dispose();
        berry = img;
        return img;
    }

    private static String initialsOf(String name)
    {
        String[] parts = name.split("[\\s'-]+");
        if (parts.length >= 2 && !parts[1].isEmpty())
        {
            return ("" + parts[0].charAt(0) + parts[1].charAt(0)).toUpperCase();
        }
        return name.substring(0, Math.min(2, name.length())).toUpperCase();
    }

    private Icons()
    {
    }
}

package com.osrsgo.ui;

import com.osrsgo.model.Species;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import javax.imageio.ImageIO;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;

/**
 * Real NPC portraits from the OSRS Wiki (chatheads preferred, renders as
 * fallback), fetched once and cached to disk. Rows fall back to the drawn
 * medallions until an image arrives; a version counter bumps on every new
 * image so the panel knows to rebuild. Images are CC BY-SA from
 * oldschool.runescape.wiki.
 */
@Slf4j
@Singleton
public class NpcImages
{
    private static final String BASE = "https://oldschool.runescape.wiki/w/Special:FilePath/";

    /** A plain wiki image name: letters, digits and light punctuation only. */
    private static final java.util.regex.Pattern SAFE_FILE_NAME =
        java.util.regex.Pattern.compile("[A-Za-z0-9 _()., '-]{1,120}\\.[Pp][Nn][Gg]");
    private static final int TARGET_HEIGHT = 28;
    private static final int MAX_WIDTH = 44;

    private final OkHttpClient httpClient;
    private final File cacheDir;
    private final Map<Integer, BufferedImage> images = new HashMap<>();
    private final Map<Integer, BufferedImage> darkened = new HashMap<>();
    private final Set<Integer> misses = new HashSet<>();
    private final Set<Integer> inFlight = new HashSet<>();
    private final AtomicInteger version = new AtomicInteger();
    private volatile Runnable onUpdate;

    // Species whose wiki file names don't follow any regular pattern
    private static final Map<String, String> OVERRIDES = new HashMap<>();

    static
    {
        OVERRIDES.put("Zulrah", "Zulrah_(serpentine).png");
        OVERRIDES.put("Zombie", "Zombie_(Level_13).png");
        OVERRIDES.put("Barbarian", "Barbarian_(Blue_Moon_Inn)_chathead.png");
        OVERRIDES.put("Grizzly Bear", "Grizzly_bear_(level_21).png");
        OVERRIDES.put("Giant Spider", "Giant_spider_(Level_27).png");
    }

    @Inject
    public NpcImages(OkHttpClient httpClient)
    {
        this.httpClient = httpClient;
        this.cacheDir = com.osrsgo.storage.PluginFiles.subDir("images");
    }

    public void setOnUpdate(Runnable onUpdate)
    {
        this.onUpdate = onUpdate;
    }

    public int getVersion()
    {
        return version.get();
    }

    /**
     * Returns the cached portrait, or null (kicking off a background fetch on
     * the first ask). Callers should fall back to the drawn medallion.
     */
    public synchronized BufferedImage cachedOrRequest(Species species)
    {
        int id = species.getId();
        BufferedImage cached = images.get(id);
        if (cached != null)
        {
            return cached;
        }
        if (misses.contains(id) || inFlight.contains(id))
        {
            return null;
        }
        File onDisk = new File(cacheDir, id + ".png");
        if (onDisk.isFile())
        {
            try
            {
                BufferedImage img = ImageIO.read(onDisk);
                if (img != null)
                {
                    images.put(id, img);
                    return img;
                }
            }
            catch (IOException e)
            {
                log.debug("bad cached image for {}", species.getName(), e);
            }
        }
        // ".miss2" is the current marker generation: renaming it once
        // invalidated every miss recorded by the buggy fetcher that gave up
        // on the first network failure. Old markers just get cleaned up.
        File legacyMiss = new File(cacheDir, id + ".miss");
        if (legacyMiss.isFile())
        {
            //noinspection ResultOfMethodCallIgnored
            legacyMiss.delete();
        }
        File missFile = new File(cacheDir, id + ".miss2");
        if (missFile.isFile())
        {
            if (System.currentTimeMillis() - missFile.lastModified() < 7L * 24 * 60 * 60 * 1000)
            {
                misses.add(id);
                return null;
            }
            // A week old: the wiki may have the file now, try again
            //noinspection ResultOfMethodCallIgnored
            missFile.delete();
        }
        inFlight.add(id);
        fetchNext(species, candidatesFor(species.getName()), 0);
        return null;
    }

    /** Darkened silhouette-ish variant for seen-but-uncaught Pokedex entries. */
    public synchronized BufferedImage darkenedCached(Species species)
    {
        BufferedImage base = cachedOrRequest(species);
        if (base == null)
        {
            return null;
        }
        return darkened.computeIfAbsent(species.getId(), id ->
        {
            BufferedImage dark = new BufferedImage(base.getWidth(), base.getHeight(), BufferedImage.TYPE_INT_ARGB);
            Graphics2D g = dark.createGraphics();
            g.drawImage(base, 0, 0, null);
            g.setComposite(java.awt.AlphaComposite.SrcAtop);
            g.setColor(new java.awt.Color(20, 20, 25, 215));
            g.fillRect(0, 0, dark.getWidth(), dark.getHeight());
            g.dispose();
            return dark;
        });
    }

    private static List<String> candidatesFor(String name)
    {
        List<String> candidates = new ArrayList<>();
        String override = OVERRIDES.get(name);
        if (override != null)
        {
            candidates.add(override);
        }
        String exact = name.replace(' ', '_');
        String lowerRest = exact.length() > 1
            ? Character.toUpperCase(exact.charAt(0)) + exact.substring(1).toLowerCase()
            : exact;
        candidates.add(exact + "_chathead.png");
        if (!lowerRest.equals(exact))
        {
            candidates.add(lowerRest + "_chathead.png");
        }
        candidates.add(exact + ".png");
        if (!lowerRest.equals(exact))
        {
            candidates.add(lowerRest + ".png");
        }
        candidates.add(exact + "_(1).png");
        if (!lowerRest.equals(exact))
        {
            candidates.add(lowerRest + "_(1).png");
        }
        return candidates;
    }

    private void fetchNext(Species species, List<String> candidates, int index)
    {
        if (index >= candidates.size())
        {
            // Plain names exhausted: many monsters only have variant-suffixed
            // files ("Zombie (Level 13).png"); ask the wiki what exists
            apiLookup(species, 0);
            return;
        }
        String file = candidates.get(index).replace("'", "%27");
        Request request = new Request.Builder().url(BASE + file + "?width=64").build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                // Network blip on one candidate must not doom the species
                log.debug("image fetch failed for {}: {}", species.getName(), e.getMessage());
                fetchNext(species, candidates, index + 1);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful() || r.body() == null)
                    {
                        fetchNext(species, candidates, index + 1);
                        return;
                    }
                    BufferedImage raw = ImageIO.read(r.body().byteStream());
                    if (raw == null)
                    {
                        fetchNext(species, candidates, index + 1);
                        return;
                    }
                    store(species, scale(raw));
                }
                catch (Exception e)
                {
                    log.debug("image decode failed for {}", species.getName(), e);
                    fetchNext(species, candidates, index + 1);
                }
            }
        });
    }

    /**
     * Asks the MediaWiki API which files start with "<Name>_(" and picks the
     * most generic-looking one. Prefixes are case-sensitive past the first
     * letter, so both name casings get a try.
     */
    private void apiLookup(Species species, int prefixIndex)
    {
        String name = species.getName().replace(' ', '_');
        String lowerRest = name.length() > 1
            ? Character.toUpperCase(name.charAt(0)) + name.substring(1).toLowerCase()
            : name;
        List<String> prefixes = new ArrayList<>();
        prefixes.add(name + "_(");
        if (!lowerRest.equals(name))
        {
            prefixes.add(lowerRest + "_(");
        }
        if (prefixIndex >= prefixes.size())
        {
            recordMiss(species);
            return;
        }
        String url;
        try
        {
            url = "https://oldschool.runescape.wiki/api.php?action=query&format=json&list=allimages&ailimit=50&aiprefix="
                + java.net.URLEncoder.encode(prefixes.get(prefixIndex), "UTF-8");
        }
        catch (java.io.UnsupportedEncodingException e)
        {
            recordMiss(species);
            return;
        }
        httpClient.newCall(new Request.Builder().url(url).build()).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                apiLookup(species, prefixIndex + 1);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response r = response)
                {
                    String best = r.isSuccessful() && r.body() != null
                        ? pickBestFile(r.body().string())
                        : null;
                    if (best == null)
                    {
                        apiLookup(species, prefixIndex + 1);
                        return;
                    }
                    List<String> single = new ArrayList<>();
                    single.add(best);
                    fetchFinal(species, single);
                }
                catch (Exception e)
                {
                    apiLookup(species, prefixIndex + 1);
                }
            }
        });
    }

    /** Most generic variant: skip seasonal/historical files, prefer chatheads, then shortest. */
    private static String pickBestFile(String json)
    {
        com.google.gson.JsonObject root = new com.google.gson.JsonParser().parse(json).getAsJsonObject();
        if (!root.has("query") || !root.getAsJsonObject("query").has("allimages"))
        {
            return null;
        }
        String best = null;
        boolean bestChathead = false;
        for (com.google.gson.JsonElement el : root.getAsJsonObject("query").getAsJsonArray("allimages"))
        {
            String file = el.getAsJsonObject().get("name").getAsString();
            String lower = file.toLowerCase();
            // The host is hardcoded above and only this file name comes back
            // from the wiki, but a name is still remote input being pasted
            // into a request, so anything that is not a plain image name is
            // dropped rather than trusted.
            if (!SAFE_FILE_NAME.matcher(file).matches())
            {
                continue;
            }
            if (!lower.endsWith(".png") || lower.contains("historical") || lower.contains("unused")
                || lower.contains("event") || lower.contains("halloween") || lower.contains("christmas")
                || lower.contains("easter"))
            {
                continue;
            }
            boolean chathead = lower.contains("chathead");
            boolean better = best == null
                || (chathead && !bestChathead)
                || (chathead == bestChathead && file.length() < best.length());
            if (better)
            {
                best = file;
                bestChathead = chathead;
            }
        }
        return best;
    }

    /** Last-chance fetch of an API-resolved file name; a miss here is final. */
    private void fetchFinal(Species species, List<String> candidates)
    {
        String file = candidates.get(0).replace("'", "%27").replace(' ', '_');
        Request request = new Request.Builder().url(BASE + file + "?width=64").build();
        httpClient.newCall(request).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                recordMiss(species);
            }

            @Override
            public void onResponse(Call call, Response response)
            {
                try (Response r = response)
                {
                    BufferedImage raw = r.isSuccessful() && r.body() != null
                        ? ImageIO.read(r.body().byteStream())
                        : null;
                    if (raw == null)
                    {
                        recordMiss(species);
                        return;
                    }
                    store(species, scale(raw));
                }
                catch (Exception e)
                {
                    recordMiss(species);
                }
            }
        });
    }

    private static BufferedImage scale(BufferedImage raw)
    {
        double factor = TARGET_HEIGHT / (double) raw.getHeight();
        int w = Math.min(MAX_WIDTH, Math.max(8, (int) Math.round(raw.getWidth() * factor)));
        int h = TARGET_HEIGHT;
        BufferedImage scaled = new BufferedImage(w, h, BufferedImage.TYPE_INT_ARGB);
        Graphics2D g = scaled.createGraphics();
        g.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BILINEAR);
        g.drawImage(raw, 0, 0, w, h, null);
        g.dispose();
        return scaled;
    }

    private synchronized void store(Species species, BufferedImage img)
    {
        images.put(species.getId(), img);
        inFlight.remove(species.getId());
        try
        {
            ImageIO.write(img, "png", new File(cacheDir, species.getId() + ".png"));
        }
        catch (IOException e)
        {
            log.debug("could not cache image for {}", species.getName(), e);
        }
        version.incrementAndGet();
        Runnable cb = onUpdate;
        if (cb != null)
        {
            cb.run();
        }
    }

    private synchronized void recordMiss(Species species)
    {
        misses.add(species.getId());
        inFlight.remove(species.getId());
        try
        {
            //noinspection ResultOfMethodCallIgnored
            new File(cacheDir, species.getId() + ".miss2").createNewFile();
        }
        catch (IOException ignored)
        {
        }
    }
}

