        }

        addHealCard(profile);
        addEggCards(profile);
        addBreedingCard(profile);
        addEssencePouch(profile);

        if (profile.mons.isEmpty())
        {
            dexContent.add(hint("No mons yet. Catch some in the Nearby tab!"));
            return;
