        breedTab.add(Box.createVerticalStrut(10));
        breedTab.add(sectionHeader("3. Make the egg"));

        JLabel status = new JLabel(" ");
        status.setFont(status.getFont().deriveFont(11f));
        status.setAlignmentX(Component.LEFT_ALIGNMENT);
