        dialog.setDefaultCloseOperation(javax.swing.WindowConstants.DISPOSE_ON_CLOSE);

        JPanel grid = new JPanel(new java.awt.GridLayout(0, 5, 4, 4));
        grid.setBackground(ColorScheme.DARK_GRAY_COLOR);
